alter table profiles              enable row level security;
alter table workspaces            enable row level security;
alter table workspace_members     enable row level security;
alter table people                enable row level security;
alter table organizations         enable row level security;
alter table projects              enable row level security;
alter table tasks                 enable row level security;
alter table goals                 enable row level security;
alter table deals                 enable row level security;
alter table invoices              enable row level security;
alter table payments              enable row level security;
alter table expenses              enable row level security;
alter table resources             enable row level security;
alter table notes                 enable row level security;
alter table meetings              enable row level security;
alter table documents             enable row level security;
alter table activities            enable row level security;
alter table relationships         enable row level security;
alter table files                 enable row level security;
alter table intelligence_events   enable row level security;
alter table audit_logs            enable row level security;

-- ─── Helper functions ─────────────────────────────────────
create or replace function is_workspace_member(ws_id uuid)
returns boolean language sql security definer stable as $$
  select exists (
    select 1 from workspace_members
    where workspace_id = ws_id
      and user_id = auth.uid()
  );
$$;

create or replace function is_workspace_admin(ws_id uuid)
returns boolean language sql security definer stable as $$
  select exists (
    select 1 from workspace_members
    where workspace_id = ws_id
      and user_id = auth.uid()
      and role in ('owner','admin')
  );
$$;





-- ─── profiles ─────────────────────────────────────────────
create policy "profiles_select" on profiles
  for select using (id = auth.uid());

create policy "profiles_insert" on profiles
  for insert with check (id = auth.uid());

create policy "profiles_update" on profiles
  for update using (id = auth.uid());

-- ─── workspaces ───────────────────────────────────────────
create policy "workspaces_select" on workspaces
  for select using (is_workspace_member(id));

create policy "workspaces_insert" on workspaces
  for insert with check (auth.uid() = owner_id);

create policy "workspaces_update" on workspaces
  for update using (owner_id = auth.uid());

-- ─── workspace_members ────────────────────────────────────
create policy "workspace_members_select" on workspace_members
  for select using (is_workspace_member(workspace_id));

create policy "workspace_members_insert" on workspace_members
  for insert with check (
    -- only the workspace owner can add members
    exists (
      select 1 from workspaces
      where id = workspace_id
        and owner_id = auth.uid()
    )
  );

create policy "workspace_members_update" on workspace_members
  for update using (is_workspace_admin(workspace_id));

create policy "workspace_members_delete" on workspace_members
  for delete using (is_workspace_admin(workspace_id));

-- ─── All workspace-isolated tables (universal pattern) ────
do $$
declare t text;
begin
  foreach t in array array[
    'people','organizations','projects','tasks','goals',
    'deals','invoices','payments','expenses','resources',
    'notes','meetings','documents','activities',
    'relationships','files','intelligence_events','audit_logs',
    'crm_customers','crm_timeline_events','crm_tasks','crm_notes',
    'crm_leads','crm_alerts','loyalty_accounts','customer_relationships',
    'crm_activity_feed','customer_ai_summaries','customer_communication_logs'
  ] loop
    execute format('
      create policy "workspace_select" on %I
        for select using (is_workspace_member(workspace_id));
      create policy "workspace_insert" on %I
        for insert with check (is_workspace_member(workspace_id));
      create policy "workspace_update" on %I
        for update using (is_workspace_member(workspace_id));
      create policy "workspace_delete" on %I
        for delete using (is_workspace_admin(workspace_id));
    ', t, t, t, t);
  end loop;
end $$;


-- ████ supabase/work-items.sql ████
-- ============================================================
-- Bumblebee — work_items
--
-- The generic work table (tasks, quotations, sales/purchase orders,
-- maintenance, stock movements…). It lived in schema-clean-install.sql but
-- was missing from schema.sql, so a fresh install broke at
-- users-access-control.sql, which extends it. Run right after schema.sql.
--
-- The checks match the unions in src/lib/database.types.ts — the app writes
-- all of these values, and the clean-install checks rejected most of them.
-- Idempotent.
-- ============================================================

create table if not exists work_items (
  id              uuid        primary key default uuid_generate_v4(),
  workspace_id    uuid        not null references workspaces(id) on delete cascade,
  title_en        text        not null,
  title_ar        text,
  type            text        not null default 'task'
                              check (type in ('task','project','milestone','action','initiative','ticket','request',
                                              'purchase_request','purchase_order','production_order','stock_movement',
                                              'maintenance','quotation','sales_order')),
  status          text        not null default 'todo'
                              check (status in ('backlog','planned','todo','in_progress','review','done','blocked','cancelled',
                                                'draft','submitted','approved','rejected','ordered','sent',
                                                'partially_received','received','expired','converted')),
  priority        text        not null default 'medium'
                              check (priority in ('critical','urgent','high','medium','low')),
  assignee_id     uuid                 references people(id) on delete set null,
  parent_id       uuid                 references work_items(id) on delete cascade,
  organization_id uuid                 references organizations(id) on delete set null,
  due_date        date,
  progress        integer     not null default 0 check (progress between 0 and 100),
  total_amount    numeric,
  tags            text[]      not null default '{}',
  metadata        jsonb       not null default '{}',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index if not exists work_items_workspace_idx on work_items(workspace_id);
create index if not exists work_items_status_idx    on work_items(workspace_id, status);
create index if not exists work_items_type_idx      on work_items(workspace_id, type);
create index if not exists work_items_assignee_idx  on work_items(assignee_id);
create index if not exists work_items_parent_idx    on work_items(parent_id);

alter table work_items enable row level security;
do $$ begin if to_regclass('work_items') is not null then execute 'drop policy if exists "workspace_select" on work_items'; end if; end $$;
do $$ begin if to_regclass('work_items') is not null then execute 'drop policy if exists "workspace_insert" on work_items'; end if; end $$;
do $$ begin if to_regclass('work_items') is not null then execute 'drop policy if exists "workspace_update" on work_items'; end if; end $$;
do $$ begin if to_regclass('work_items') is not null then execute 'drop policy if exists "workspace_delete" on work_items'; end if; end $$;

create policy "workspace_select" on work_items for select using (is_workspace_member(workspace_id));
create policy "workspace_insert" on work_items for insert with check (is_workspace_member(workspace_id));
create policy "workspace_update" on work_items for update using (is_workspace_member(workspace_id));
create policy "workspace_delete" on work_items for delete using (is_workspace_admin(workspace_id));
do $$ begin if to_regclass('work_items') is not null then execute 'drop trigger if exists set_updated_at on work_items'; end if; end $$;
create trigger set_updated_at before update on work_items
  for each row execute function update_updated_at();

grant select, insert, update, delete on work_items to authenticated;


-- ████ supabase/users-access-control.sql ████
-- Users, Roles & Access Control Migration
-- Sprint C: Multi-user access with role-based permissions

-- ═══════════════════════════════════════════════════════════
-- Extend workspace_members with role + department + permissions
-- ═══════════════════════════════════════════════════════════

DO $$ BEGIN
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS role TEXT DEFAULT 'viewer';
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS department TEXT;
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS permissions JSONB DEFAULT '{}';
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS display_name TEXT;
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'active';
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS invited_by UUID;
  ALTER TABLE workspace_members ADD COLUMN IF NOT EXISTS invited_at TIMESTAMPTZ;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

-- ═══════════════════════════════════════════════════════════
-- Invitations table
-- ═══════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS workspace_invitations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  display_name TEXT,
  role TEXT NOT NULL DEFAULT 'viewer',
  department TEXT,
  permissions JSONB DEFAULT '{}',
  invited_by UUID REFERENCES auth.users(id),
  status TEXT DEFAULT 'pending', -- pending, accepted, expired, cancelled
  token TEXT UNIQUE DEFAULT encode(gen_random_bytes(32), 'hex'),
  expires_at TIMESTAMPTZ DEFAULT (now() + interval '7 days'),
  accepted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_invitations_workspace ON workspace_invitations(workspace_id);
CREATE INDEX IF NOT EXISTS idx_invitations_email ON workspace_invitations(email);
CREATE INDEX IF NOT EXISTS idx_invitations_token ON workspace_invitations(token);

ALTER TABLE workspace_invitations ENABLE ROW LEVEL SECURITY;

-- Helper functions (SECURITY DEFINER avoids circular RLS on workspace_members)
CREATE OR REPLACE FUNCTION can_manage_invitations(ws_id uuid)
RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM workspace_members
    WHERE workspace_id = ws_id AND user_id = auth.uid()
      AND role IN ('owner', 'admin')
  );
$$;

CREATE OR REPLACE FUNCTION is_workspace_member_direct(ws_id uuid)
RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM workspace_members
    WHERE workspace_id = ws_id AND user_id = auth.uid()
  );
$$;

CREATE POLICY "invitations_select_v2" ON workspace_invitations
  FOR SELECT USING (is_workspace_member_direct(workspace_id));

CREATE POLICY "invitations_insert_v2" ON workspace_invitations
  FOR INSERT WITH CHECK (can_manage_invitations(workspace_id));

CREATE POLICY "invitations_update_v2" ON workspace_invitations
  FOR UPDATE USING (can_manage_invitations(workspace_id));

CREATE POLICY "invitations_delete_v2" ON workspace_invitations
  FOR DELETE USING (can_manage_invitations(workspace_id));

-- ═══════════════════════════════════════════════════════════
-- Role definitions (reference, not enforced in DB)
-- ═══════════════════════════════════════════════════════════

COMMENT ON TABLE workspace_members IS '
Roles:
  owner    — Full access, can delete workspace
  admin    — Full access, cannot delete workspace
  manager  — All modules, can approve/release
  finance  — Finance, invoices, payments, approve financial steps
  sales    — Customers, quotations, sales orders
  production — Production orders, manufacturing stages, QC
  warehouse — Inventory, stock movements, material requirements
  viewer   — Read-only access to all modules
';

-- ═══════════════════════════════════════════════════════════
-- Release/Approval States for work_items
-- ═══════════════════════════════════════════════════════════

DO $$ BEGIN
  ALTER TABLE work_items ADD COLUMN IF NOT EXISTS release_status TEXT DEFAULT 'draft';
  ALTER TABLE work_items ADD COLUMN IF NOT EXISTS release_history JSONB DEFAULT '[]';
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

-- release_status values: draft, waiting_approval, released, blocked, rejected
-- release_history: [{role, user_id, action, timestamp, note}]

