-- ████ supabase/invite-flow.sql ████
-- Invite Flow Migration (Sprint B)
-- Two SECURITY DEFINER RPCs that make the /invite/<token> page work:
--   get_invitation_by_token — safe public preview (workspace name, role, email)
--   accept_invitation       — joins the signed-in user to the workspace
-- The token itself is the secret (32 random bytes, unguessable), so exposing
-- a lookup by token to anon is safe — it only reveals what the invite email
-- already contains.
-- Idempotent — safe to re-run. Paste into the Supabase dashboard SQL editor.

-- ─── Preview an invitation (anon + authenticated) ──────────
create or replace function get_invitation_by_token(invite_token text)
returns json
language plpgsql
security definer
stable
as $$
declare
  inv record;
begin
  select i.id, i.email, i.role, i.department, i.display_name,
         i.status, i.expires_at, i.workspace_id,
         w.name as workspace_name,
         coalesce(p.full_name, p.email) as inviter_name
    into inv
    from workspace_invitations i
    join workspaces w on w.id = i.workspace_id
    left join profiles p on p.id = i.invited_by
   where i.token = invite_token;

  if not found then
    return json_build_object('ok', false, 'error_code', 'not_found');
  end if;

  if inv.status = 'accepted' then
    return json_build_object('ok', false, 'error_code', 'already_accepted',
                             'workspace_name', inv.workspace_name);
  end if;

  if inv.status <> 'pending' then
    return json_build_object('ok', false, 'error_code', 'cancelled');
  end if;

  if inv.expires_at < now() then
    return json_build_object('ok', false, 'error_code', 'expired',
                             'workspace_name', inv.workspace_name);
  end if;

  return json_build_object(
    'ok', true,
    'email', inv.email,
    'role', inv.role,
    'department', inv.department,
    'display_name', inv.display_name,
    'workspace_name', inv.workspace_name,
    'inviter_name', inv.inviter_name,
    'expires_at', inv.expires_at
  );
end;
$$;

-- ─── Accept an invitation (authenticated only) ─────────────
create or replace function accept_invitation(invite_token text)
returns json
language plpgsql
security definer
as $$
declare
  inv record;
  caller_email text;
  member_role text;
begin
  if auth.uid() is null then
    return json_build_object('ok', false, 'error_code', 'not_signed_in');
  end if;

  select i.*, w.name as workspace_name
    into inv
    from workspace_invitations i
    join workspaces w on w.id = i.workspace_id
   where i.token = invite_token;

  if not found then
    return json_build_object('ok', false, 'error_code', 'not_found');
  end if;

  if inv.status = 'accepted' then
    return json_build_object('ok', false, 'error_code', 'already_accepted',
                             'workspace_name', inv.workspace_name);
  end if;

  if inv.status <> 'pending' then
    return json_build_object('ok', false, 'error_code', 'cancelled');
  end if;

  if inv.expires_at < now() then
    update workspace_invitations set status = 'expired' where id = inv.id;
    return json_build_object('ok', false, 'error_code', 'expired',
                             'workspace_name', inv.workspace_name);
  end if;

  -- The invite must be accepted by the address it was sent to.
  caller_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if caller_email = '' or caller_email <> lower(trim(inv.email)) then
    return json_build_object('ok', false, 'error_code', 'email_mismatch',
                             'invited_email', inv.email);
  end if;

  -- workspace_members.role has a CHECK (owner/admin/member/viewer).
  -- Richer invite roles (e.g. manager) map to 'member' for the constraint
  -- and keep the original title in permissions for the UI / future H4 sprint.
  member_role := case
    when inv.role in ('admin', 'member', 'viewer') then inv.role
    else 'member'
  end;

  insert into workspace_members
      (workspace_id, user_id, role, department, display_name,
       permissions, status, invited_by, invited_at)
  values
      (inv.workspace_id, auth.uid(), member_role, inv.department, inv.display_name,
       coalesce(inv.permissions, '{}'::jsonb) || jsonb_build_object('invite_role', inv.role),
       'active', inv.invited_by, inv.created_at)
  on conflict (workspace_id, user_id) do nothing;

  update workspace_invitations
     set status = 'accepted', accepted_at = now()
   where id = inv.id;

  return json_build_object(
    'ok', true,
    'workspace_id', inv.workspace_id,
    'workspace_name', inv.workspace_name,
    'role', member_role
  );
end;
$$;

-- ─── Grants ────────────────────────────────────────────────
grant execute on function get_invitation_by_token(text) to anon, authenticated;
grant execute on function accept_invitation(text) to authenticated;


-- ████ supabase/fix-invitation-rls.sql ████
-- ═══════════════════════════════════════════════════════════
-- FIX: workspace_invitations RLS policies
--
-- Root cause of "error creating user" on invite:
--
-- 1. Original policy used FOR ALL USING(...) which can cause
--    issues with INSERT (needs WITH CHECK, not USING)
-- 2. The subquery inside the policy hits workspace_members
--    which itself has RLS enabled → potential circular RLS
-- 3. Role check included 'manager' but workspace_members
--    CHECK constraint only allows: owner/admin/member/viewer
--
-- Fix: Use SECURITY DEFINER function for the permission check
-- to bypass RLS on workspace_members during policy evaluation.
-- ═══════════════════════════════════════════════════════════

-- Step 1: Drop ALL existing policies on workspace_invitations
DO $$
DECLARE
  pol RECORD;
BEGIN
  FOR pol IN
    SELECT policyname FROM pg_policies
    WHERE tablename = 'workspace_invitations' AND schemaname = 'public'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON workspace_invitations', pol.policyname);
    RAISE NOTICE 'Dropped policy: %', pol.policyname;
  END LOOP;
END $$;

-- Step 2: Create helper function (SECURITY DEFINER bypasses RLS)
CREATE OR REPLACE FUNCTION can_manage_invitations(ws_id uuid)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1 FROM workspace_members
    WHERE workspace_id = ws_id
      AND user_id = auth.uid()
      AND role IN ('owner', 'admin')
  );
$$;

CREATE OR REPLACE FUNCTION is_workspace_member_direct(ws_id uuid)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1 FROM workspace_members
    WHERE workspace_id = ws_id
      AND user_id = auth.uid()
  );
$$;

-- Step 3: Create clean policies using the helper functions

-- SELECT: any workspace member can see invitations
CREATE POLICY "invitations_select_v2" ON workspace_invitations
  FOR SELECT USING (is_workspace_member_direct(workspace_id));

-- INSERT: owner or admin can create invitations
CREATE POLICY "invitations_insert_v2" ON workspace_invitations
  FOR INSERT WITH CHECK (can_manage_invitations(workspace_id));

-- UPDATE: owner or admin can update invitations (e.g. cancel)
CREATE POLICY "invitations_update_v2" ON workspace_invitations
  FOR UPDATE USING (can_manage_invitations(workspace_id));

-- DELETE: owner or admin can delete invitations
CREATE POLICY "invitations_delete_v2" ON workspace_invitations
  FOR DELETE USING (can_manage_invitations(workspace_id));

-- Step 4: Ensure RLS is enabled
ALTER TABLE workspace_invitations ENABLE ROW LEVEL SECURITY;

-- Step 5: Verify — run this to confirm policies are in place
-- SELECT policyname, cmd, qual, with_check
-- FROM pg_policies
-- WHERE tablename = 'workspace_invitations';

-- ═══════════════════════════════════════════════════════════
-- DONE. After running this:
-- 1. Old broken policies are removed
-- 2. New policies use SECURITY DEFINER functions
-- 3. owner + admin can create invitations
-- 4. No more circular RLS issues
-- ═══════════════════════════════════════════════════════════


-- ████ supabase/premium-auth-onboarding-notifications.sql ████
-- ═══════════════════════════════════════════════════════════
-- Bumblebee — Premium Auth + Onboarding + Notifications Migration
-- ═══════════════════════════════════════════════════════════

-- ─── Notifications table ─────────────────────────────────

CREATE TABLE IF NOT EXISTS notifications (
  id           uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id      uuid REFERENCES auth.users(id) ON DELETE CASCADE, -- null = broadcast
  type         text NOT NULL DEFAULT 'info',
  title        text NOT NULL,
  body         text NOT NULL DEFAULT '',
  status       text NOT NULL DEFAULT 'unread' CHECK (status IN ('unread', 'read', 'action_required')),
  link         text,
  metadata     jsonb DEFAULT '{}',
  created_at   timestamptz DEFAULT now(),
  updated_at   timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_notifications_workspace ON notifications(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, status);

-- RLS
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
do $$ begin if to_regclass('notifications') is not null then execute 'drop policy if exists "notifications_select" on notifications'; end if; end $$;
CREATE POLICY "notifications_select" ON notifications FOR SELECT USING (
  workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid())
  AND (user_id IS NULL OR user_id = auth.uid())
);
do $$ begin if to_regclass('notifications') is not null then execute 'drop policy if exists "notifications_insert" on notifications'; end if; end $$;
CREATE POLICY "notifications_insert" ON notifications FOR INSERT WITH CHECK (
  workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid())
);
do $$ begin if to_regclass('notifications') is not null then execute 'drop policy if exists "notifications_update" on notifications'; end if; end $$;
CREATE POLICY "notifications_update" ON notifications FOR UPDATE USING (
  (user_id = auth.uid()) OR
  (user_id IS NULL AND workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()))
);

-- Enable realtime
ALTER PUBLICATION supabase_realtime ADD TABLE notifications;

-- ─── Helper function: create notification ─────────────────

CREATE OR REPLACE FUNCTION create_notification(
  p_workspace_id uuid,
  p_user_id uuid,
  p_type text,
  p_title text,
  p_body text DEFAULT '',
  p_link text DEFAULT NULL,
  p_status text DEFAULT 'unread'
) RETURNS uuid AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO notifications (workspace_id, user_id, type, title, body, link, status)
  VALUES (p_workspace_id, p_user_id, p_type, p_title, p_body, p_link, p_status)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ─── Auto-notification on release status change ───────────

CREATE OR REPLACE FUNCTION notify_on_release_change()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.metadata->>'release_status' IS DISTINCT FROM OLD.metadata->>'release_status' THEN
    INSERT INTO notifications (workspace_id, user_id, type, title, body, link)
    VALUES (
      NEW.workspace_id,
      NULL, -- broadcast
      CASE
        WHEN NEW.metadata->>'release_status' = 'released' THEN 'release_approved'
        WHEN NEW.metadata->>'release_status' = 'rejected' THEN 'release_rejected'
        ELSE 'approval_needed'
      END,
      COALESCE(NEW.metadata->>'title', NEW.title, 'Work Item') || ' — ' || COALESCE(NEW.metadata->>'release_status', 'updated'),
      'Release status changed to ' || COALESCE(NEW.metadata->>'release_status', 'unknown'),
      '/' || CASE WHEN NEW.type = 'sales_order' THEN 'orders' ELSE 'work' END
    );
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
do $$ begin if to_regclass('work_items') is not null then execute 'drop trigger if exists trg_release_notification on work_items'; end if; end $$;
CREATE TRIGGER trg_release_notification
  AFTER UPDATE ON work_items
  FOR EACH ROW
  EXECUTE FUNCTION notify_on_release_change();

-- ═══════════════════════════════════════════════════════════
-- Done. Tables: notifications
-- Triggers: release status change → auto-notification
-- ═══════════════════════════════════════════════════════════


-- ████ supabase/admin-users-analytics.sql ████
-- ═══════════════════════════════════════════════════════════
-- Bumblebee Sprint 2: Admin Users + Permissions + Analytics
-- Migration: admin-users-analytics.sql
-- ═══════════════════════════════════════════════════════════

-- ─── 1. Add permissions JSONB to workspace_members ───────
-- Stores granular per-user permissions as { module: [actions] }

ALTER TABLE workspace_members
  ADD COLUMN IF NOT EXISTS permissions JSONB DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS department TEXT,
  ADD COLUMN IF NOT EXISTS display_name TEXT,
  ADD COLUMN IF NOT EXISTS job_title TEXT;

COMMENT ON COLUMN workspace_members.permissions IS 'Granular permissions map: { "orders": ["view","create","edit"], "inventory": ["view"] }';
COMMENT ON COLUMN workspace_members.department IS 'Employee department (sales, production, warehouse, etc.)';
COMMENT ON COLUMN workspace_members.display_name IS 'Display name for the user in the workspace';
COMMENT ON COLUMN workspace_members.job_title IS 'Employee job title';

-- ─── 2. Role templates table ────────────────────────────
-- Stores customizable role templates per workspace

CREATE TABLE IF NOT EXISTS role_templates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  name_ar TEXT,
  description TEXT,
  description_ar TEXT,
  permissions JSONB NOT NULL DEFAULT '{}',
  risk_level TEXT NOT NULL DEFAULT 'low' CHECK (risk_level IN ('low', 'medium', 'high')),
  is_system BOOLEAN DEFAULT FALSE,
  color TEXT DEFAULT 'bg-slate-100 text-slate-600',
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(workspace_id, name)
);

COMMENT ON TABLE role_templates IS 'Custom role templates with granular permission maps';

-- RLS for role_templates
ALTER TABLE role_templates ENABLE ROW LEVEL SECURITY;

CREATE POLICY "role_templates_workspace_read" ON role_templates
  FOR SELECT USING (
    workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid())
  );

CREATE POLICY "role_templates_admin_write" ON role_templates
  FOR ALL USING (
    workspace_id IN (
      SELECT workspace_id FROM workspace_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
  );

-- ─── 3. Saved reports table ─────────────────────────────
-- Stores user-created custom report configurations

CREATE TABLE IF NOT EXISTS saved_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  name_ar TEXT,
  config JSONB NOT NULL DEFAULT '{}',
  is_shared BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

COMMENT ON TABLE saved_reports IS 'User-saved custom report configurations with data source, filters, grouping, metrics';
COMMENT ON COLUMN saved_reports.config IS '{ dataSource, dateRange, groupBy, metric, chartType, filters: [{field, operator, value}] }';

-- RLS for saved_reports
ALTER TABLE saved_reports ENABLE ROW LEVEL SECURITY;

CREATE POLICY "saved_reports_read" ON saved_reports
  FOR SELECT USING (
    workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid())
    AND (is_shared = TRUE OR created_by = auth.uid())
  );

CREATE POLICY "saved_reports_write_own" ON saved_reports
  FOR INSERT WITH CHECK (
    workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid())
    AND created_by = auth.uid()
  );

CREATE POLICY "saved_reports_update_own" ON saved_reports
  FOR UPDATE USING (created_by = auth.uid());

CREATE POLICY "saved_reports_delete_own" ON saved_reports
  FOR DELETE USING (created_by = auth.uid());

-- ─── 4. Permission check function ──────────────────────
-- Server-side permission check for RLS policies

CREATE OR REPLACE FUNCTION check_user_permission(
  p_workspace_id UUID,
  p_module TEXT,
  p_action TEXT
) RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role TEXT;
  v_permissions JSONB;
  v_module_perms JSONB;
BEGIN
  -- Get user's role and permissions
  SELECT role, COALESCE(permissions, '{}'::jsonb)
  INTO v_role, v_permissions
  FROM workspace_members
  WHERE workspace_id = p_workspace_id AND user_id = auth.uid();

  -- Owner and admin have full access
  IF v_role IN ('owner', 'admin') THEN
    RETURN TRUE;
  END IF;

  -- Check granular permissions
  v_module_perms := v_permissions -> p_module;
  IF v_module_perms IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN v_module_perms ? p_action;
END;
$$;

COMMENT ON FUNCTION check_user_permission IS 'Check if current user has specific permission on a module within a workspace';

-- ─── 5. Indexes ─────────────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_workspace_members_permissions
  ON workspace_members USING GIN (permissions);

CREATE INDEX IF NOT EXISTS idx_role_templates_workspace
  ON role_templates(workspace_id);

CREATE INDEX IF NOT EXISTS idx_saved_reports_workspace
  ON saved_reports(workspace_id);

CREATE INDEX IF NOT EXISTS idx_saved_reports_created_by
  ON saved_reports(created_by);

-- ─── 6. Updated_at trigger ──────────────────────────────

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'role_templates_updated_at') THEN
    CREATE TRIGGER role_templates_updated_at
      BEFORE UPDATE ON role_templates
      FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'saved_reports_updated_at') THEN
    CREATE TRIGGER saved_reports_updated_at
      BEFORE UPDATE ON saved_reports
      FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
  END IF;
END;
$$;

