-- ████ supabase/production-planning-foundation.sql ████
-- ============================================================
-- Bumblebee — Production Planning Foundation
-- تخطيط الإنتاج وأوامر التشغيل
-- ============================================================

-- ─── Production Orders (أوامر التشغيل) ───────────────────

CREATE TABLE IF NOT EXISTS production_orders (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id    UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  po_number       TEXT NOT NULL,
  title           TEXT NOT NULL,
  sales_order_id  UUID REFERENCES work_items(id) ON DELETE SET NULL,
  design_brief_id UUID REFERENCES design_briefs(id) ON DELETE SET NULL,
  customer_id     UUID REFERENCES organizations(id) ON DELETE SET NULL,
  customer_name   TEXT,
  -- Assignment
  assigned_station  TEXT,
  assigned_workers  JSONB DEFAULT '[]'::jsonb,
  -- Scheduling
  priority        TEXT DEFAULT 'medium'
                  CHECK (priority IN ('critical','urgent','high','medium','low')),
  start_date      DATE,
  due_date        DATE,
  completed_date  DATE,
  -- Status
  status          TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending','pattern','cutting','sewing','edgebanding','drilling','assembly','finishing','quality_check','packing','ready','delivered','cancelled')),
  current_stage   TEXT DEFAULT 'pending',
  progress        INTEGER DEFAULT 0,
  -- Materials
  materials_summary JSONB DEFAULT '[]'::jsonb,
  -- Notes
  notes           TEXT,
  metadata        JSONB DEFAULT '{}'::jsonb,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_prod_orders_workspace ON production_orders(workspace_id);
CREATE INDEX IF NOT EXISTS idx_prod_orders_status    ON production_orders(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_prod_orders_so        ON production_orders(sales_order_id);
CREATE INDEX IF NOT EXISTS idx_prod_orders_design    ON production_orders(design_brief_id);

-- ─── Cutting List Items (قائمة التقطيع) ──────────────────

CREATE TABLE IF NOT EXISTS cutting_list_items (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  production_order_id UUID NOT NULL REFERENCES production_orders(id) ON DELETE CASCADE,
  piece_number        INTEGER NOT NULL DEFAULT 1,
  part_name           TEXT NOT NULL,
  material            TEXT,
  thickness           NUMERIC(10,2),
  width               NUMERIC(10,2),
  length              NUMERIC(10,2),
  qty                 INTEGER DEFAULT 1,
  edge_top            TEXT,
  edge_bottom         TEXT,
  edge_left           TEXT,
  edge_right          TEXT,
  grain_direction     TEXT CHECK (grain_direction IN ('horizontal','vertical','none')),
  cnc_program         TEXT,
  notes               TEXT,
  completed           BOOLEAN DEFAULT false,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_cutting_list_po ON cutting_list_items(production_order_id);

-- ─── Production Stage Log (سجل مراحل التصنيع) ────────────

CREATE TABLE IF NOT EXISTS production_stage_log (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  production_order_id UUID NOT NULL REFERENCES production_orders(id) ON DELETE CASCADE,
  stage               TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','in_progress','completed','skipped')),
  started_at          TIMESTAMPTZ,
  completed_at        TIMESTAMPTZ,
  duration_minutes    INTEGER,
  worker_name         TEXT,
  station             TEXT,
  notes               TEXT,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_stage_log_po ON production_stage_log(production_order_id);

-- ─── RLS ──────────────────────────────────────────────────

ALTER TABLE production_orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE cutting_list_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE production_stage_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY "production_orders_workspace" ON production_orders
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "cutting_list_items_workspace" ON cutting_list_items
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "production_stage_log_workspace" ON production_stage_log
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- ─── Triggers ─────────────────────────────────────────────
do $$ begin if to_regclass('production_orders') is not null then execute 'drop trigger if exists trg_prod_orders_updated on production_orders'; end if; end $$;
CREATE TRIGGER trg_prod_orders_updated BEFORE UPDATE ON production_orders
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
do $$ begin if to_regclass('cutting_list_items') is not null then execute 'drop trigger if exists trg_cutting_list_updated on cutting_list_items'; end if; end $$;
CREATE TRIGGER trg_cutting_list_updated BEFORE UPDATE ON cutting_list_items
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
do $$ begin if to_regclass('production_stage_log') is not null then execute 'drop trigger if exists trg_stage_log_updated on production_stage_log'; end if; end $$;
CREATE TRIGGER trg_stage_log_updated BEFORE UPDATE ON production_stage_log
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();


-- ████ supabase/quality-control-foundation.sql ████
-- ============================================================
-- Bumblebee — Quality Control Foundation
-- مراقبة الجودة
-- ============================================================

-- ─── QC Inspections (فحوصات الجودة) ──────────────────────

CREATE TABLE IF NOT EXISTS qc_inspections (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  inspection_number   TEXT NOT NULL,
  production_order_id UUID REFERENCES production_orders(id) ON DELETE SET NULL,
  sales_order_id      UUID REFERENCES work_items(id) ON DELETE SET NULL,
  customer_name       TEXT,
  inspector_name      TEXT,
  inspection_type     TEXT DEFAULT 'final'
                      CHECK (inspection_type IN ('in_process','pre_assembly','final','pre_delivery','re_inspection')),
  status              TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','in_progress','passed','failed','conditional')),
  -- Checklist (JSON array of {id, label_en, label_ar, passed, notes})
  checklist           JSONB DEFAULT '[]'::jsonb,
  overall_score       INTEGER,
  result_notes        TEXT,
  inspected_at        TIMESTAMPTZ,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_qc_inspections_ws ON qc_inspections(workspace_id);
CREATE INDEX IF NOT EXISTS idx_qc_inspections_po ON qc_inspections(production_order_id);
CREATE INDEX IF NOT EXISTS idx_qc_inspections_status ON qc_inspections(workspace_id, status);

-- ─── QC Defects (عيوب التصنيع) ────────────────────────────

CREATE TABLE IF NOT EXISTS qc_defects (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  inspection_id     UUID NOT NULL REFERENCES qc_inspections(id) ON DELETE CASCADE,
  defect_number     TEXT NOT NULL,
  title             TEXT NOT NULL,
  severity          TEXT DEFAULT 'minor'
                    CHECK (severity IN ('critical','major','minor','cosmetic')),
  category          TEXT DEFAULT 'other'
                    CHECK (category IN ('dimension','surface','material','assembly','finish','hardware','edge','color','other')),
  description       TEXT,
  location          TEXT,
  photo_url         TEXT,
  status            TEXT NOT NULL DEFAULT 'open'
                    CHECK (status IN ('open','rework','re_inspected','accepted','rejected')),
  rework_notes      TEXT,
  reworked_by       TEXT,
  reworked_at       TIMESTAMPTZ,
  metadata          JSONB DEFAULT '{}'::jsonb,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_qc_defects_insp ON qc_defects(inspection_id);
CREATE INDEX IF NOT EXISTS idx_qc_defects_ws   ON qc_defects(workspace_id);

-- ─── RLS ──────────────────────────────────────────────────

ALTER TABLE qc_inspections ENABLE ROW LEVEL SECURITY;
ALTER TABLE qc_defects ENABLE ROW LEVEL SECURITY;

CREATE POLICY "qc_inspections_workspace" ON qc_inspections
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "qc_defects_workspace" ON qc_defects
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- ─── Storage bucket for defect photos ─────────────────────

INSERT INTO storage.buckets (id, name, public)
VALUES ('qc-photos', 'qc-photos', true)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "qc_photos_upload" ON storage.objects
  FOR INSERT WITH CHECK (bucket_id = 'qc-photos');

CREATE POLICY "qc_photos_read" ON storage.objects
  FOR SELECT USING (bucket_id = 'qc-photos');

-- ─── Triggers ─────────────────────────────────────────────
do $$ begin if to_regclass('qc_inspections') is not null then execute 'drop trigger if exists trg_qc_inspections_updated on qc_inspections'; end if; end $$;
CREATE TRIGGER trg_qc_inspections_updated BEFORE UPDATE ON qc_inspections
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
do $$ begin if to_regclass('qc_defects') is not null then execute 'drop trigger if exists trg_qc_defects_updated on qc_defects'; end if; end $$;
CREATE TRIGGER trg_qc_defects_updated BEFORE UPDATE ON qc_defects
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();


-- ████ supabase/delivery-installation-foundation.sql ████
-- ============================================================
-- Bumblebee — Delivery & Installation Foundation
-- التسليم والتركيب
-- ============================================================

-- ─── Deliveries (التسليمات) ─────────────────────────────────

CREATE TABLE IF NOT EXISTS deliveries (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  delivery_number     TEXT NOT NULL,
  production_order_id UUID REFERENCES production_orders(id) ON DELETE SET NULL,
  sales_order_id      UUID REFERENCES work_items(id) ON DELETE SET NULL,
  customer_name       TEXT,
  customer_phone      TEXT,
  delivery_address    TEXT,
  delivery_date       DATE,
  delivery_time_slot  TEXT,  -- e.g. "10:00-12:00"
  driver_name         TEXT,
  vehicle_info        TEXT,
  status              TEXT NOT NULL DEFAULT 'scheduled'
                      CHECK (status IN ('scheduled','loading','in_transit','delivered','failed','cancelled')),
  loading_notes       TEXT,
  delivery_notes      TEXT,
  recipient_name      TEXT,   -- who received it
  recipient_phone     TEXT,
  delivered_at        TIMESTAMPTZ,
  delivery_photo_url  TEXT,
  num_pieces          INTEGER DEFAULT 0,
  num_packages        INTEGER DEFAULT 0,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_deliveries_ws ON deliveries(workspace_id);
CREATE INDEX IF NOT EXISTS idx_deliveries_po ON deliveries(production_order_id);
CREATE INDEX IF NOT EXISTS idx_deliveries_status ON deliveries(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_deliveries_date ON deliveries(workspace_id, delivery_date);

-- ─── Installations (التركيبات) ──────────────────────────────

CREATE TABLE IF NOT EXISTS installations (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  installation_number TEXT NOT NULL,
  delivery_id         UUID REFERENCES deliveries(id) ON DELETE SET NULL,
  sales_order_id      UUID REFERENCES work_items(id) ON DELETE SET NULL,
  customer_name       TEXT,
  customer_phone      TEXT,
  site_address        TEXT,
  scheduled_date      DATE,
  scheduled_time_slot TEXT,
  team_leader         TEXT,
  team_members        JSONB DEFAULT '[]'::jsonb,  -- array of names
  status              TEXT NOT NULL DEFAULT 'scheduled'
                      CHECK (status IN ('scheduled','in_progress','completed','on_hold','cancelled')),
  -- Checklist (JSON array of {id, label_en, label_ar, passed, notes})
  checklist           JSONB DEFAULT '[]'::jsonb,
  -- Snag list (JSON array of {id, title, severity, status, photo_url, notes})
  snag_list           JSONB DEFAULT '[]'::jsonb,
  completion_notes    TEXT,
  customer_rating     INTEGER CHECK (customer_rating IS NULL OR (customer_rating >= 1 AND customer_rating <= 5)),
  customer_feedback   TEXT,
  signature_url       TEXT,
  started_at          TIMESTAMPTZ,
  completed_at        TIMESTAMPTZ,
  photos              JSONB DEFAULT '[]'::jsonb,  -- array of {url, caption, type}
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_installations_ws ON installations(workspace_id);
CREATE INDEX IF NOT EXISTS idx_installations_delivery ON installations(delivery_id);
CREATE INDEX IF NOT EXISTS idx_installations_status ON installations(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_installations_date ON installations(workspace_id, scheduled_date);

-- ─── RLS ──────────────────────────────────────────────────

ALTER TABLE deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE installations ENABLE ROW LEVEL SECURITY;

CREATE POLICY "deliveries_workspace" ON deliveries
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "installations_workspace" ON installations
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- ─── Storage bucket for installation photos & signatures ──

INSERT INTO storage.buckets (id, name, public)
