-- ████ supabase/advanced-features-foundation.sql ████
-- ============================================================
-- Bumblebee — Advanced Features Foundation
-- أدوات متقدمة
-- ============================================================

-- ─── Cost Entries (بنود التكاليف) ───────────────────────────

CREATE TABLE IF NOT EXISTS cost_entries (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  sales_order_id      UUID REFERENCES work_items(id) ON DELETE SET NULL,
  production_order_id UUID REFERENCES production_orders(id) ON DELETE SET NULL,
  cost_type           TEXT NOT NULL DEFAULT 'material'
                      CHECK (cost_type IN ('material','labor','overhead','subcontract','transport','other')),
  description         TEXT NOT NULL,
  quantity            NUMERIC(12,2) DEFAULT 1,
  unit_cost           NUMERIC(12,2) NOT NULL DEFAULT 0,
  total_cost          NUMERIC(12,2) NOT NULL DEFAULT 0,
  currency            TEXT DEFAULT 'EGP',
  date                DATE DEFAULT CURRENT_DATE,
  supplier            TEXT,
  notes               TEXT,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_cost_entries_ws ON cost_entries(workspace_id);
CREATE INDEX IF NOT EXISTS idx_cost_entries_so ON cost_entries(sales_order_id);
CREATE INDEX IF NOT EXISTS idx_cost_entries_po ON cost_entries(production_order_id);
CREATE INDEX IF NOT EXISTS idx_cost_entries_type ON cost_entries(workspace_id, cost_type);

-- ─── Branches (الفروع) ─────────────────────────────────────

CREATE TABLE IF NOT EXISTS branches (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  branch_code         TEXT NOT NULL,
  name                TEXT NOT NULL,
  name_ar             TEXT,
  address             TEXT,
  phone               TEXT,
  manager_name        TEXT,
  branch_type         TEXT DEFAULT 'factory'
                      CHECK (branch_type IN ('factory','showroom','warehouse','office')),
  is_active           BOOLEAN DEFAULT true,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_branches_ws ON branches(workspace_id);

-- ─── RLS ──────────────────────────────────────────────────

ALTER TABLE cost_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE branches ENABLE ROW LEVEL SECURITY;

CREATE POLICY "cost_entries_workspace" ON cost_entries
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "branches_workspace" ON branches
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- ─── Triggers ─────────────────────────────────────────────
do $$ begin if to_regclass('cost_entries') is not null then execute 'drop trigger if exists trg_cost_entries_updated on cost_entries'; end if; end $$;
CREATE TRIGGER trg_cost_entries_updated BEFORE UPDATE ON cost_entries
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
do $$ begin if to_regclass('branches') is not null then execute 'drop trigger if exists trg_branches_updated on branches'; end if; end $$;
CREATE TRIGGER trg_branches_updated BEFORE UPDATE ON branches
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();


-- ████ supabase/hr-workforce-foundation.sql ████
-- ============================================================
-- Bumblebee — HR & Workforce Foundation
-- الموارد البشرية
-- ============================================================

-- ─── Employees (الموظفين) ───────────────────────────────────

CREATE TABLE IF NOT EXISTS employees (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  employee_number     TEXT NOT NULL,
  full_name           TEXT NOT NULL,
  full_name_ar        TEXT,
  phone               TEXT,
  email               TEXT,
  national_id         TEXT,
  department          TEXT DEFAULT 'production'
                      CHECK (department IN ('production','finishing','assembly','design','sales','admin','warehouse','delivery','management')),
  job_title           TEXT,
  job_title_ar        TEXT,
  employment_type     TEXT DEFAULT 'full_time'
                      CHECK (employment_type IN ('full_time','part_time','contract','daily')),
  status              TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active','on_leave','suspended','terminated')),
  hire_date           DATE,
  termination_date    DATE,
  salary              NUMERIC(12,2),
  salary_type         TEXT DEFAULT 'monthly'
                      CHECK (salary_type IN ('monthly','weekly','daily','hourly')),
  photo_url           TEXT,
  emergency_contact   TEXT,
  emergency_phone     TEXT,
  address             TEXT,
  -- Skills (JSON array of {skill, level: 1-5})
  skills              JSONB DEFAULT '[]'::jsonb,
  -- Documents (JSON array of {type, name, url, expiry_date})
  documents           JSONB DEFAULT '[]'::jsonb,
  notes               TEXT,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_employees_ws ON employees(workspace_id);
CREATE INDEX IF NOT EXISTS idx_employees_dept ON employees(workspace_id, department);
CREATE INDEX IF NOT EXISTS idx_employees_status ON employees(workspace_id, status);

-- ─── Attendance (الحضور والانصراف) ──────────────────────────

CREATE TABLE IF NOT EXISTS attendance (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  employee_id         UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,
  date                DATE NOT NULL,
  check_in            TIMESTAMPTZ,
  check_out           TIMESTAMPTZ,
  status              TEXT NOT NULL DEFAULT 'present'
                      CHECK (status IN ('present','absent','late','half_day','holiday','sick_leave','annual_leave','excused')),
  overtime_hours      NUMERIC(4,1) DEFAULT 0,
  notes               TEXT,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_attendance_ws ON attendance(workspace_id);
CREATE INDEX IF NOT EXISTS idx_attendance_emp ON attendance(employee_id);
CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(workspace_id, date);
CREATE UNIQUE INDEX IF NOT EXISTS idx_attendance_emp_date ON attendance(employee_id, date);

-- ─── Leave Requests (طلبات الإجازات) ────────────────────────

CREATE TABLE IF NOT EXISTS leave_requests (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  employee_id         UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,
  leave_type          TEXT NOT NULL DEFAULT 'annual'
                      CHECK (leave_type IN ('annual','sick','unpaid','emergency','maternity','other')),
  start_date          DATE NOT NULL,
  end_date            DATE NOT NULL,
  days                INTEGER NOT NULL DEFAULT 1,
  reason              TEXT,
  status              TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','approved','rejected','cancelled')),
  approved_by         TEXT,
  approved_at         TIMESTAMPTZ,
  metadata            JSONB DEFAULT '{}'::jsonb,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_leave_ws ON leave_requests(workspace_id);
CREATE INDEX IF NOT EXISTS idx_leave_emp ON leave_requests(employee_id);
CREATE INDEX IF NOT EXISTS idx_leave_status ON leave_requests(workspace_id, status);

-- ─── RLS ──────────────────────────────────────────────────

ALTER TABLE employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance ENABLE ROW LEVEL SECURITY;
ALTER TABLE leave_requests ENABLE ROW LEVEL SECURITY;

CREATE POLICY "employees_workspace" ON employees
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "attendance_workspace" ON attendance
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "leave_requests_workspace" ON leave_requests
  USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- ─── Storage bucket for employee photos & documents ───────

INSERT INTO storage.buckets (id, name, public)
VALUES ('employee-files', 'employee-files', true)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "employee_files_upload" ON storage.objects
  FOR INSERT WITH CHECK (bucket_id = 'employee-files');

CREATE POLICY "employee_files_read" ON storage.objects
  FOR SELECT USING (bucket_id = 'employee-files');

-- ─── Triggers ─────────────────────────────────────────────
do $$ begin if to_regclass('employees') is not null then execute 'drop trigger if exists trg_employees_updated on employees'; end if; end $$;
CREATE TRIGGER trg_employees_updated BEFORE UPDATE ON employees
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
do $$ begin if to_regclass('attendance') is not null then execute 'drop trigger if exists trg_attendance_updated on attendance'; end if; end $$;
CREATE TRIGGER trg_attendance_updated BEFORE UPDATE ON attendance
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
do $$ begin if to_regclass('leave_requests') is not null then execute 'drop trigger if exists trg_leave_requests_updated on leave_requests'; end if; end $$;
CREATE TRIGGER trg_leave_requests_updated BEFORE UPDATE ON leave_requests
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();


-- ████ supabase/loyalty-foundation.sql ████
-- ═══════════════════════════════════════════════════════════
-- LOYALTY PROGRAM FOUNDATION
-- برنامج الولاء — الجداول الأساسية
--
-- Tables: loyalty_programs, loyalty_tiers, loyalty_rules,
--         loyalty_members, loyalty_transactions, loyalty_redemptions,
--         loyalty_rewards, shopify_connections, shopify_orders,
--         shopify_sync_log
--
-- All tables have RLS enabled with workspace_id isolation.
-- Points are computed from immutable transactions — never
-- update balances directly. Cached balances on loyalty_members
-- are updated via triggers for read performance.
-- ═══════════════════════════════════════════════════════════

-- ─── LOYALTY PROGRAMS ────────────────────────────────────

CREATE TABLE IF NOT EXISTS loyalty_programs (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  name_en           TEXT NOT NULL DEFAULT 'Loyalty Program',
  name_ar           TEXT DEFAULT 'برنامج الولاء',

  -- Earning configuration
  points_per_amount INT NOT NULL DEFAULT 100,       -- points awarded
  amount_per_points NUMERIC(10,2) NOT NULL DEFAULT 10, -- per this amount in currency
  currency          TEXT NOT NULL DEFAULT 'EGP',

  -- Redemption configuration
  redemption_points INT NOT NULL DEFAULT 1000,      -- points needed
  redemption_value  NUMERIC(10,2) NOT NULL DEFAULT 10, -- discount given
  min_redemption    INT NOT NULL DEFAULT 500,        -- minimum points to redeem
  max_discount      NUMERIC(10,2),                   -- max discount per redemption (null = unlimited)

  -- Channels
  earn_online       BOOLEAN NOT NULL DEFAULT TRUE,
  earn_instore      BOOLEAN NOT NULL DEFAULT TRUE,
  redeem_online     BOOLEAN NOT NULL DEFAULT TRUE,
  redeem_instore    BOOLEAN NOT NULL DEFAULT TRUE,

  -- Expiry
  points_expiry_days INT,                            -- null = never expire

  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(workspace_id)  -- one program per workspace
);

ALTER TABLE loyalty_programs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_programs_workspace" ON loyalty_programs
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── LOYALTY TIERS ───────────────────────────────────────

CREATE TABLE IF NOT EXISTS loyalty_tiers (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  program_id        UUID NOT NULL REFERENCES loyalty_programs(id) ON DELETE CASCADE,

  slug              TEXT NOT NULL,                    -- bronze, silver, gold, vip
  name_en           TEXT NOT NULL,
  name_ar           TEXT,
  color             TEXT DEFAULT '#CD7F32',
  min_spend         NUMERIC(14,2) NOT NULL DEFAULT 0, -- cumulative spend threshold
  earning_multiplier NUMERIC(4,2) NOT NULL DEFAULT 1.0,
  sort_order        INT NOT NULL DEFAULT 0,

  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(workspace_id, slug)
);

ALTER TABLE loyalty_tiers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_tiers_workspace" ON loyalty_tiers
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── LOYALTY RULES ───────────────────────────────────────

CREATE TABLE IF NOT EXISTS loyalty_rules (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  program_id        UUID NOT NULL REFERENCES loyalty_programs(id) ON DELETE CASCADE,

  name_en           TEXT NOT NULL,
  name_ar           TEXT,
  type              TEXT NOT NULL CHECK (type IN ('spend', 'category_bonus', 'first_purchase', 'birthday', 'campaign', 'referral', 'threshold')),
  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'scheduled', 'paused', 'expired')),

  -- Rule configuration (varies by type)
  points_awarded    INT,                              -- flat points bonus
  multiplier        NUMERIC(4,2),                     -- earning multiplier
  min_amount        NUMERIC(14,2),                    -- minimum spend or threshold
  category_filter   TEXT[],                           -- product categories (for category_bonus)
  starts_at         TIMESTAMPTZ,                     -- campaign start
  ends_at           TIMESTAMPTZ,                     -- campaign end

  description_en    TEXT,
  description_ar    TEXT,
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  priority          INT NOT NULL DEFAULT 0,           -- higher = checked first
  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE loyalty_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_rules_workspace" ON loyalty_rules
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── LOYALTY MEMBERS ─────────────────────────────────────
-- Extends people/organizations with loyalty-specific data

CREATE TABLE IF NOT EXISTS loyalty_members (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  program_id        UUID NOT NULL REFERENCES loyalty_programs(id) ON DELETE CASCADE,

  -- Link to existing Bumblebee entities
  person_id         UUID REFERENCES people(id),
  organization_id   UUID REFERENCES organizations(id),

  -- Core identity (denormalized for fast lookup)
  member_number     TEXT NOT NULL,                    -- e.g., "LYL-00001"
  name_en           TEXT NOT NULL,
  name_ar           TEXT,
  email             TEXT,
  phone             TEXT,                             -- primary lookup key for MENA

  -- Shopify link
  shopify_customer_id TEXT,                           -- Shopify customer GID

  -- Cached balances (computed from transactions via trigger)
  current_points    INT NOT NULL DEFAULT 0,
  lifetime_points   INT NOT NULL DEFAULT 0,
  redeemed_points   INT NOT NULL DEFAULT 0,
  expired_points    INT NOT NULL DEFAULT 0,

  -- Tier (cached, recomputed on spend change)
  tier_id           UUID REFERENCES loyalty_tiers(id),
  tier_slug         TEXT DEFAULT 'bronze',

  -- Stats (cached, updated on each transaction)
  total_spend       NUMERIC(14,2) NOT NULL DEFAULT 0,
  order_count       INT NOT NULL DEFAULT 0,
  last_purchase_at  TIMESTAMPTZ,
  last_earn_at      TIMESTAMPTZ,
  last_redeem_at    TIMESTAMPTZ,

  -- Preferences
  favorite_categories TEXT[],
  opted_in          BOOLEAN NOT NULL DEFAULT TRUE,

  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(workspace_id, member_number),
  UNIQUE(workspace_id, shopify_customer_id)
);

-- Indexes for fast lookup (POS staff search)
CREATE INDEX IF NOT EXISTS idx_loyalty_members_phone ON loyalty_members (workspace_id, phone);
CREATE INDEX IF NOT EXISTS idx_loyalty_members_email ON loyalty_members (workspace_id, email);
CREATE INDEX IF NOT EXISTS idx_loyalty_members_name  ON loyalty_members (workspace_id, name_en);
CREATE INDEX IF NOT EXISTS idx_loyalty_members_shopify ON loyalty_members (workspace_id, shopify_customer_id);

ALTER TABLE loyalty_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_members_workspace" ON loyalty_members
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── LOYALTY TRANSACTIONS ────────────────────────────────
-- IMMUTABLE audit trail — never update, only insert.
-- Points balance is computed from SUM of transactions.

CREATE TABLE IF NOT EXISTS loyalty_transactions (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  member_id         UUID NOT NULL REFERENCES loyalty_members(id) ON DELETE CASCADE,

  type              TEXT NOT NULL CHECK (type IN ('earned', 'redeemed', 'adjusted', 'expired', 'reversed', 'bonus')),
  points            INT NOT NULL,                     -- positive for earn/bonus, negative for redeem/expire/reverse
  balance_after     INT NOT NULL,                     -- snapshot of balance after this tx

  source            TEXT NOT NULL CHECK (source IN ('shopify', 'store', 'admin', 'system')),

  -- Order reference
  order_id          TEXT,                             -- Shopify order ID or internal ref
  order_amount      NUMERIC(14,2),                    -- purchase amount
  receipt_number    TEXT,

  -- Metadata
  rule_id           UUID REFERENCES loyalty_rules(id),   -- which rule triggered this
  staff_name        TEXT,                             -- for in-store transactions
  notes             TEXT,

  -- Reversal link
  reversed_tx_id    UUID REFERENCES loyalty_transactions(id),

  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
  -- No updated_at — transactions are immutable
);

CREATE INDEX IF NOT EXISTS idx_loyalty_tx_member ON loyalty_transactions (member_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_loyalty_tx_workspace ON loyalty_transactions (workspace_id, created_at DESC);

ALTER TABLE loyalty_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_transactions_workspace" ON loyalty_transactions
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── LOYALTY REDEMPTIONS ─────────────────────────────────

CREATE TABLE IF NOT EXISTS loyalty_redemptions (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  member_id         UUID NOT NULL REFERENCES loyalty_members(id) ON DELETE CASCADE,
  transaction_id    UUID NOT NULL REFERENCES loyalty_transactions(id),

  channel           TEXT NOT NULL CHECK (channel IN ('online', 'offline')),
  points_redeemed   INT NOT NULL,
  discount_amount   NUMERIC(14,2) NOT NULL,
  currency          TEXT NOT NULL DEFAULT 'EGP',

  -- Online redemption (Shopify)
  shopify_price_rule_id TEXT,
  shopify_discount_code TEXT,                         -- unique code for this redemption
  shopify_order_id  TEXT,                             -- if used

  -- Offline redemption
  staff_id          UUID,
  staff_name        TEXT,

  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'used', 'expired', 'cancelled')),
  expires_at        TIMESTAMPTZ,

  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE loyalty_redemptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_redemptions_workspace" ON loyalty_redemptions
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── SHOPIFY CONNECTIONS ─────────────────────────────────
-- Encrypted credentials — access_token is stored encrypted,
-- NEVER returned to the frontend.

CREATE TABLE IF NOT EXISTS shopify_connections (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  store_url         TEXT NOT NULL,                    -- e.g., "my-store.myshopify.com"
  access_token_enc  TEXT NOT NULL,                    -- encrypted via pgcrypto
  webhook_secret    TEXT NOT NULL,                    -- for HMAC validation
  api_version       TEXT NOT NULL DEFAULT '2024-01',

  -- Status
  is_connected      BOOLEAN NOT NULL DEFAULT FALSE,
  last_sync_at      TIMESTAMPTZ,
  last_error        TEXT,

  -- Sync settings
  sync_customers    BOOLEAN NOT NULL DEFAULT TRUE,
  sync_orders       BOOLEAN NOT NULL DEFAULT TRUE,
  auto_award_points BOOLEAN NOT NULL DEFAULT TRUE,
  sync_metafields   BOOLEAN NOT NULL DEFAULT TRUE,

  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(workspace_id)
);

ALTER TABLE shopify_connections ENABLE ROW LEVEL SECURITY;
-- IMPORTANT: Never return access_token_enc to frontend
CREATE POLICY "shopify_connections_workspace" ON shopify_connections
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── SHOPIFY ORDERS ──────────────────────────────────────
-- Raw order data from Shopify for reference and audit

CREATE TABLE IF NOT EXISTS shopify_orders (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  shopify_order_id  TEXT NOT NULL,                    -- Shopify order GID
  shopify_order_number TEXT,                          -- human-readable #1001
  shopify_customer_id TEXT,

  -- Matched Bumblebee member
  member_id         UUID REFERENCES loyalty_members(id),

  -- Order data
  total_amount      NUMERIC(14,2) NOT NULL,
  currency          TEXT NOT NULL DEFAULT 'EGP',
  line_items        JSONB DEFAULT '[]',
  financial_status  TEXT,                             -- paid, refunded, partially_refunded
  fulfillment_status TEXT,

  -- Points awarded
  points_awarded    INT NOT NULL DEFAULT 0,
  rules_applied     JSONB DEFAULT '[]',               -- which rules contributed

  -- Processing
  processed         BOOLEAN NOT NULL DEFAULT FALSE,
  processed_at      TIMESTAMPTZ,
  error_message     TEXT,

  raw_payload       JSONB,                            -- full Shopify webhook payload (for debugging)

  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(workspace_id, shopify_order_id)
);

ALTER TABLE shopify_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "shopify_orders_workspace" ON shopify_orders
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── SHOPIFY SYNC LOG ────────────────────────────────────
-- Every webhook event and sync action is logged here

CREATE TABLE IF NOT EXISTS shopify_sync_log (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  event_type        TEXT NOT NULL,                    -- order_created, customer_created, points_awarded, etc.
  status            TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('success', 'failed', 'skipped', 'pending')),

  shopify_order_id  TEXT,
  shopify_customer_id TEXT,
  member_id         UUID REFERENCES loyalty_members(id),
  member_name       TEXT,

  points_delta      INT,
  details           TEXT NOT NULL,
  error_message     TEXT,

  raw_payload       JSONB,                            -- webhook payload for debugging

  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sync_log_workspace ON shopify_sync_log (workspace_id, created_at DESC);

ALTER TABLE shopify_sync_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "shopify_sync_log_workspace" ON shopify_sync_log
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── LOYALTY REWARDS (Phase 2) ───────────────────────────
-- Catalog of redeemable rewards beyond simple discounts

CREATE TABLE IF NOT EXISTS loyalty_rewards (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  name_en           TEXT NOT NULL,
  name_ar           TEXT,
  description_en    TEXT,
  description_ar    TEXT,
  points_cost       INT NOT NULL,
  reward_type       TEXT NOT NULL DEFAULT 'discount' CHECK (reward_type IN ('discount', 'product', 'experience', 'voucher')),

  -- For discount type
  discount_amount   NUMERIC(14,2),
  discount_percent  NUMERIC(5,2),

  -- Stock
  quantity_available INT,                             -- null = unlimited
  quantity_redeemed  INT NOT NULL DEFAULT 0,

  image_url         TEXT,
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order        INT NOT NULL DEFAULT 0,

  metadata          JSONB DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE loyalty_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "loyalty_rewards_workspace" ON loyalty_rewards
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── FUNCTIONS: Points Calculation ───────────────────────

-- Calculate points for an order based on active rules
CREATE OR REPLACE FUNCTION calculate_loyalty_points(
  p_workspace_id UUID,
  p_order_amount NUMERIC,
  p_categories TEXT[] DEFAULT '{}',
  p_member_tier TEXT DEFAULT 'bronze',
  p_is_first_purchase BOOLEAN DEFAULT FALSE
)
RETURNS TABLE(total_points INT, rules_applied JSONB) AS $$
DECLARE
  v_program loyalty_programs%ROWTYPE;
  v_rule RECORD;
  v_base_points INT := 0;
  v_multiplier NUMERIC := 1.0;
  v_bonus_points INT := 0;
  v_tier_multiplier NUMERIC := 1.0;
  v_rules JSONB := '[]'::JSONB;
BEGIN
  -- Get program config
  SELECT * INTO v_program FROM loyalty_programs
    WHERE workspace_id = p_workspace_id AND is_active = TRUE LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::INT, '[]'::JSONB;
    RETURN;
  END IF;

  -- Base spend rule: points_per_amount for every amount_per_points spent
  v_base_points := FLOOR(p_order_amount / v_program.amount_per_points) * v_program.points_per_amount;
  v_rules := v_rules || jsonb_build_object('type', 'spend', 'points', v_base_points);

  -- Get tier multiplier
  SELECT earning_multiplier INTO v_tier_multiplier
    FROM loyalty_tiers
    WHERE workspace_id = p_workspace_id AND slug = p_member_tier AND is_active = TRUE
    LIMIT 1;
  v_tier_multiplier := COALESCE(v_tier_multiplier, 1.0);

  -- Apply active rules
  FOR v_rule IN
    SELECT * FROM loyalty_rules
    WHERE workspace_id = p_workspace_id
      AND is_active = TRUE
      AND status = 'active'
      AND (starts_at IS NULL OR starts_at <= NOW())
      AND (ends_at IS NULL OR ends_at >= NOW())
    ORDER BY priority DESC
  LOOP
    CASE v_rule.type
      WHEN 'category_bonus' THEN
        -- Check if any purchased category matches the rule's filter
        IF v_rule.category_filter IS NOT NULL AND v_rule.category_filter && p_categories THEN
          v_multiplier := GREATEST(v_multiplier, COALESCE(v_rule.multiplier, 1.0));
          v_rules := v_rules || jsonb_build_object('type', 'category_bonus', 'rule_id', v_rule.id, 'multiplier', v_rule.multiplier);
        END IF;

      WHEN 'campaign' THEN
        -- Campaign multiplier overrides base if higher
        v_multiplier := GREATEST(v_multiplier, COALESCE(v_rule.multiplier, 1.0));
        v_rules := v_rules || jsonb_build_object('type', 'campaign', 'rule_id', v_rule.id, 'multiplier', v_rule.multiplier);

      WHEN 'first_purchase' THEN
        IF p_is_first_purchase AND v_rule.points_awarded IS NOT NULL THEN
          v_bonus_points := v_bonus_points + v_rule.points_awarded;
          v_rules := v_rules || jsonb_build_object('type', 'first_purchase', 'rule_id', v_rule.id, 'points', v_rule.points_awarded);
        END IF;

      WHEN 'threshold' THEN
        IF p_order_amount >= COALESCE(v_rule.min_amount, 0) AND v_rule.points_awarded IS NOT NULL THEN
          v_bonus_points := v_bonus_points + v_rule.points_awarded;
          v_rules := v_rules || jsonb_build_object('type', 'threshold', 'rule_id', v_rule.id, 'points', v_rule.points_awarded);
        END IF;

      ELSE NULL;
    END CASE;
  END LOOP;

  -- Final calculation: (base_points × max_multiplier × tier_multiplier) + bonus_points
  total_points := FLOOR(v_base_points * v_multiplier * v_tier_multiplier) + v_bonus_points;
  rules_applied := v_rules;
  RETURN NEXT;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ─── TRIGGERS: Update cached balances ────────────────────

-- After inserting a loyalty transaction, update the member's cached balances
CREATE OR REPLACE FUNCTION update_member_balance()
RETURNS TRIGGER AS $$
BEGIN
  UPDATE loyalty_members SET
    current_points = (
      SELECT COALESCE(SUM(points), 0) FROM loyalty_transactions WHERE member_id = NEW.member_id
    ),
    lifetime_points = (
      SELECT COALESCE(SUM(points), 0) FROM loyalty_transactions
      WHERE member_id = NEW.member_id AND points > 0
    ),
    redeemed_points = (
      SELECT COALESCE(ABS(SUM(points)), 0) FROM loyalty_transactions
      WHERE member_id = NEW.member_id AND type = 'redeemed'
    ),
    expired_points = (
      SELECT COALESCE(ABS(SUM(points)), 0) FROM loyalty_transactions
      WHERE member_id = NEW.member_id AND type = 'expired'
    ),
    last_earn_at = CASE WHEN NEW.type IN ('earned', 'bonus') THEN NOW() ELSE last_earn_at END,
    last_redeem_at = CASE WHEN NEW.type = 'redeemed' THEN NOW() ELSE last_redeem_at END,
    updated_at = NOW()
  WHERE id = NEW.member_id;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER trg_update_member_balance
  AFTER INSERT ON loyalty_transactions
  FOR EACH ROW
  EXECUTE FUNCTION update_member_balance();

-- ─── FUNCTION: Customer Matching ─────────────────────────

-- Match a Shopify customer to a loyalty member
-- Priority: shopify_customer_id > email > phone
CREATE OR REPLACE FUNCTION match_shopify_customer(
  p_workspace_id UUID,
  p_shopify_customer_id TEXT,
  p_email TEXT DEFAULT NULL,
  p_phone TEXT DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
  v_member_id UUID;
BEGIN
  -- 1. Exact Shopify ID match
  IF p_shopify_customer_id IS NOT NULL THEN
    SELECT id INTO v_member_id FROM loyalty_members
      WHERE workspace_id = p_workspace_id
        AND shopify_customer_id = p_shopify_customer_id
        AND is_active = TRUE
      LIMIT 1;
    IF FOUND THEN RETURN v_member_id; END IF;
  END IF;

  -- 2. Email match
  IF p_email IS NOT NULL AND p_email != '' THEN
    SELECT id INTO v_member_id FROM loyalty_members
      WHERE workspace_id = p_workspace_id
        AND LOWER(email) = LOWER(p_email)
        AND is_active = TRUE
      LIMIT 1;
    IF FOUND THEN
      -- Link Shopify ID for future fast matching
      IF p_shopify_customer_id IS NOT NULL THEN
        UPDATE loyalty_members SET shopify_customer_id = p_shopify_customer_id, updated_at = NOW()
          WHERE id = v_member_id AND shopify_customer_id IS NULL;
      END IF;
      RETURN v_member_id;
    END IF;
  END IF;

  -- 3. Phone match (normalize: strip +, spaces, leading 0s)
  IF p_phone IS NOT NULL AND p_phone != '' THEN
    SELECT id INTO v_member_id FROM loyalty_members
      WHERE workspace_id = p_workspace_id
        AND REGEXP_REPLACE(phone, '[^0-9]', '', 'g') = REGEXP_REPLACE(p_phone, '[^0-9]', '', 'g')
        AND is_active = TRUE
      LIMIT 1;
    IF FOUND THEN
      IF p_shopify_customer_id IS NOT NULL THEN
        UPDATE loyalty_members SET shopify_customer_id = p_shopify_customer_id, updated_at = NOW()
          WHERE id = v_member_id AND shopify_customer_id IS NULL;
      END IF;
      RETURN v_member_id;
    END IF;
  END IF;

  -- No match found
  RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ─── FUNCTION: Tier Recalculation ────────────────────────

CREATE OR REPLACE FUNCTION recalculate_member_tier(p_member_id UUID)
RETURNS TEXT AS $$
DECLARE
  v_member loyalty_members%ROWTYPE;
  v_new_tier RECORD;
BEGIN
  SELECT * INTO v_member FROM loyalty_members WHERE id = p_member_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- Find highest tier the member qualifies for based on total_spend
  SELECT * INTO v_new_tier FROM loyalty_tiers
    WHERE workspace_id = v_member.workspace_id
      AND is_active = TRUE
      AND min_spend <= v_member.total_spend
    ORDER BY min_spend DESC
    LIMIT 1;

  IF FOUND AND v_new_tier.slug != v_member.tier_slug THEN
    UPDATE loyalty_members SET
      tier_id = v_new_tier.id,
      tier_slug = v_new_tier.slug,
      updated_at = NOW()
    WHERE id = p_member_id;
    RETURN v_new_tier.slug;
  END IF;

  RETURN v_member.tier_slug;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ════════════════════════════════════════════════════════════
-- POINTS EXPIRY — Process expired points (Sprint L4)
-- ════════════════════════════════════════════════════════════

-- Call periodically (e.g. daily cron or pg_cron) to expire stale points.
-- Reads program-level expiry settings from loyalty_programs.metadata:
--   { "expiry_days": 365, "protected_balance": 500, "warning_days": 14 }
--
-- For each member with eligible points older than expiry_days:
--   1. Skip if member balance ≤ protected_balance
--   2. Calculate expired amount = oldest un-expired batch amount
--   3. Insert "expired" transaction (immutable audit)
--   4. Log the event

CREATE OR REPLACE FUNCTION process_points_expiry(p_workspace_id UUID)
RETURNS TABLE(member_id UUID, expired_points INT, new_balance INT) AS $$
DECLARE
  v_program     RECORD;
  v_expiry_days INT;
  v_protected   INT;
  v_cutoff      TIMESTAMPTZ;
  v_member      RECORD;
  v_expire_sum  INT;
  v_new_bal     INT;
BEGIN
  -- Get program settings
  SELECT * INTO v_program FROM loyalty_programs
    WHERE workspace_id = p_workspace_id AND is_active = TRUE
    LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Read expiry config from program metadata
  v_expiry_days := COALESCE((v_program.metadata->>'expiry_days')::INT, 0);
  v_protected   := COALESCE((v_program.metadata->>'protected_balance')::INT, 0);

  -- If expiry is disabled (0 or null), do nothing
  IF v_expiry_days <= 0 THEN
    RETURN;
  END IF;

  v_cutoff := NOW() - (v_expiry_days || ' days')::INTERVAL;

  -- Find members with "earned" or "bonus" transactions older than cutoff
  -- that haven't been offset by a corresponding "expired" transaction
  FOR v_member IN
    SELECT m.id, m.current_points, m.name_en
    FROM loyalty_members m
    WHERE m.workspace_id = p_workspace_id
      AND m.current_points > v_protected
      AND m.is_active = TRUE
      AND EXISTS (
        SELECT 1 FROM loyalty_transactions t
        WHERE t.member_id = m.id
          AND t.type IN ('earned', 'bonus')
          AND t.created_at < v_cutoff
          -- Only un-expired: no matching expired tx referencing this earn
          AND NOT EXISTS (
            SELECT 1 FROM loyalty_transactions t2
            WHERE t2.member_id = m.id
              AND t2.type = 'expired'
              AND t2.notes LIKE '%expiry of batch%' || t.id::TEXT || '%'
          )
      )
  LOOP
    -- Sum all un-expired earned/bonus points older than cutoff
    SELECT COALESCE(SUM(t.points), 0) INTO v_expire_sum
    FROM loyalty_transactions t
    WHERE t.member_id = v_member.id
      AND t.type IN ('earned', 'bonus')
      AND t.created_at < v_cutoff
      AND NOT EXISTS (
        SELECT 1 FROM loyalty_transactions t2
        WHERE t2.member_id = v_member.id
          AND t2.type = 'expired'
          AND t2.notes LIKE '%expiry of batch%' || t.id::TEXT || '%'
      );

    -- Don't expire more than current balance minus protected amount
    v_expire_sum := LEAST(v_expire_sum, v_member.current_points - v_protected);

    IF v_expire_sum > 0 THEN
      v_new_bal := v_member.current_points - v_expire_sum;

      -- Insert immutable expiry transaction
      INSERT INTO loyalty_transactions (
        workspace_id, member_id, type, points, balance_after,
        source, notes
      ) VALUES (
        p_workspace_id, v_member.id, 'expired', -v_expire_sum, v_new_bal,
        'system',
        'Points expiry policy (' || v_expiry_days || ' days). Expired ' || v_expire_sum || ' points.'
      );

      -- balance is updated by the trigger (update_member_balance)

      member_id      := v_member.id;
      expired_points := v_expire_sum;
      new_balance    := v_new_bal;
      RETURN NEXT;
    END IF;
  END LOOP;

  RETURN;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ████ supabase/shopify-sync-expansion.sql ████
-- ═══════════════════════════════════════════════════════════
-- SHOPIFY SYNC EXPANSION
-- Per-entity sync directions (import / export / two-way / off),
-- generic Bumblebee ↔ Shopify entity mapping, and sync run history.
--
-- Run AFTER loyalty-foundation.sql (extends shopify_connections).
-- ═══════════════════════════════════════════════════════════

-- ─── 1. Sync direction config on the connection ──────────
-- Shape:
-- {
--   "entities": {
--     "products":  "both" | "import" | "export" | "off",
--     "inventory": "both" | "import" | "export" | "off",
--     "orders":    "import" | "off",
--     "customers": "both" | "import" | "export" | "off",
--     "loyalty":   "export" | "off",
--     "analytics": "import" | "off"
--   },
--   "conflict_policy": "latest" | "shopify" | "bumblebee",
--   "auto_sync": true,
--   "sync_interval_minutes": 30
-- }
-- ─── 0. Dev Dashboard auth (client credentials grant) ─────
-- Shopify replaced static custom-app tokens (shpat_) with the
-- Dev Dashboard: apps hold a Client ID + Secret and exchange them
-- for short-lived (~24h) access tokens at /admin/oauth/access_token.
-- access_token_enc now doubles as the cached short-lived token.
ALTER TABLE shopify_connections
  ADD COLUMN IF NOT EXISTS auth_mode TEXT NOT NULL DEFAULT 'access_token',  -- 'access_token' | 'client_credentials'
  ADD COLUMN IF NOT EXISTS client_id TEXT,
  ADD COLUMN IF NOT EXISTS client_secret_enc TEXT,
  ADD COLUMN IF NOT EXISTS token_expires_at TIMESTAMPTZ;

ALTER TABLE shopify_connections
  ADD COLUMN IF NOT EXISTS sync_config JSONB NOT NULL DEFAULT '{
    "entities": {
      "products": "import",
      "inventory": "off",
      "orders": "import",
      "customers": "import",
      "loyalty": "export",
      "analytics": "import"
    },
    "conflict_policy": "latest",
    "auto_sync": true,
    "sync_interval_minutes": 30
  }'::jsonb;

-- ─── 2. Entity mapping table ──────────────────────────────
-- One row per linked record pair. Lets pulls/pushes upsert
-- instead of duplicating, and powers conflict resolution.

CREATE TABLE IF NOT EXISTS shopify_entity_map (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id    UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  entity_type     TEXT NOT NULL,           -- 'product' | 'variant' | 'customer' | 'order' | 'inventory_item'
  thoth_id        UUID,                    -- products.id / people.id / sales_orders.id / resources.id
  thoth_table     TEXT,                    -- 'products' | 'people' | 'sales_orders' | 'resources' | 'work_items'
  shopify_id      TEXT NOT NULL,           -- numeric Shopify ID or GID
  shopify_handle  TEXT,                    -- product handle / order number (human-readable)

  -- Conflict resolution
  last_synced_at  TIMESTAMPTZ,
  last_direction  TEXT,                    -- 'import' | 'export'
  bumblebee_hash      TEXT,                    -- content hash at last sync (change detection)
  shopify_hash    TEXT,

  metadata        JSONB DEFAULT '{}',
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE(workspace_id, entity_type, shopify_id)
);

CREATE INDEX IF NOT EXISTS idx_shopify_entity_map_bumblebee
  ON shopify_entity_map(workspace_id, entity_type, thoth_id);

ALTER TABLE shopify_entity_map ENABLE ROW LEVEL SECURITY;
do $$ begin if to_regclass('shopify_entity_map') is not null then execute 'drop policy if exists "shopify_entity_map_workspace" on shopify_entity_map'; end if; end $$;
CREATE POLICY "shopify_entity_map_workspace" ON shopify_entity_map
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));

-- ─── 3. Sync run history ──────────────────────────────────
-- One row per sync run (manual "Sync Now" or scheduled).

CREATE TABLE IF NOT EXISTS shopify_sync_runs (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id    UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,

  entity_type     TEXT NOT NULL,           -- 'products' | 'inventory' | 'orders' | 'customers' | 'full'
  direction       TEXT NOT NULL,           -- 'import' | 'export' | 'both'
  trigger_kind    TEXT NOT NULL DEFAULT 'manual',  -- 'manual' | 'scheduled' | 'webhook'

  status          TEXT NOT NULL DEFAULT 'running',  -- 'running' | 'success' | 'partial' | 'failed'
  records_pulled  INT NOT NULL DEFAULT 0,
  records_pushed  INT NOT NULL DEFAULT 0,
  records_skipped INT NOT NULL DEFAULT 0,
  conflicts       INT NOT NULL DEFAULT 0,
  error_message   TEXT,

  started_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  finished_at     TIMESTAMPTZ,

  metadata        JSONB DEFAULT '{}'
);

CREATE INDEX IF NOT EXISTS idx_shopify_sync_runs_ws
  ON shopify_sync_runs(workspace_id, started_at DESC);

ALTER TABLE shopify_sync_runs ENABLE ROW LEVEL SECURITY;
do $$ begin if to_regclass('shopify_sync_runs') is not null then execute 'drop policy if exists "shopify_sync_runs_workspace" on shopify_sync_runs'; end if; end $$;
CREATE POLICY "shopify_sync_runs_workspace" ON shopify_sync_runs
  USING (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id))
  WITH CHECK (workspace_id IN (SELECT id FROM workspaces WHERE id = workspace_id));


-- ████ supabase/product-bom-foundation.sql ████
-- ============================================================
-- Bumblebee ERP — Product Catalog + BOM Foundation Migration
-- ============================================================
-- OPTIONAL. Currently products are stored in the resources
-- table (type = 'product') with BOM, costing, and stages
-- in the metadata JSON field.
--
-- Run this migration when you need dedicated tables for
-- better querying, indexing, or complex BOM operations.
-- ============================================================

-- Products catalog
CREATE TABLE IF NOT EXISTS products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name_en TEXT NOT NULL,
  name_ar TEXT,
  sku TEXT,
  category TEXT,
  description TEXT,
  active BOOLEAN DEFAULT TRUE,
  -- Dimensions (cm)
  width NUMERIC(8,2),
  height NUMERIC(8,2),
  depth NUMERIC(8,2),
  thickness NUMERIC(8,2),
  weight NUMERIC(8,2),
  -- Materials
  main_material TEXT,
  secondary_material TEXT,
  finish TEXT,
  paint TEXT,
  hardware TEXT,
  edge_banding TEXT,
  -- Costing
  material_cost NUMERIC(12,2) DEFAULT 0,
  labor_cost NUMERIC(12,2) DEFAULT 0,
  machine_cost NUMERIC(12,2) DEFAULT 0,
  overhead_cost NUMERIC(12,2) DEFAULT 0,
  suggested_price NUMERIC(12,2),
  currency TEXT DEFAULT 'EGP',
  -- Meta
  tags TEXT[] DEFAULT '{}',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Bill of Materials
CREATE TABLE IF NOT EXISTS product_bom (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  material TEXT NOT NULL,
  quantity NUMERIC(10,3) DEFAULT 1,
  unit TEXT DEFAULT 'piece',
  cost_per_unit NUMERIC(12,2) DEFAULT 0,
  notes TEXT,
  sort_order INTEGER DEFAULT 0,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Manufacturing stages / templates
CREATE TABLE IF NOT EXISTS product_stages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  sort_order INTEGER DEFAULT 0,
  estimated_hours NUMERIC(6,2),
  department TEXT,
  notes TEXT,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE product_bom ENABLE ROW LEVEL SECURITY;
ALTER TABLE product_stages ENABLE ROW LEVEL SECURITY;

CREATE POLICY "workspace_products" ON products
  FOR ALL USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "workspace_product_bom" ON product_bom
  FOR ALL USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "workspace_product_stages" ON product_stages
  FOR ALL USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- Indexes
CREATE INDEX IF NOT EXISTS idx_products_workspace ON products(workspace_id);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(workspace_id, category);
CREATE INDEX IF NOT EXISTS idx_products_sku ON products(workspace_id, sku);
CREATE INDEX IF NOT EXISTS idx_product_bom_product ON product_bom(product_id);
CREATE INDEX IF NOT EXISTS idx_product_stages_product ON product_stages(product_id);


-- ████ supabase/quotations-foundation.sql ████
-- ============================================================
-- Bumblebee ERP — Quotations Foundation Migration
-- ============================================================
-- This migration is OPTIONAL. The quotations module currently
-- stores data in the work_items table (type = 'quotation' or
-- 'sales_order') with line items in the metadata JSON field.
--
-- Run this migration ONLY when you need dedicated tables for
-- better querying, indexing, or reporting on quotation data.
-- ============================================================

-- Quotations table (dedicated, if needed in future)
CREATE TABLE IF NOT EXISTS quotations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  quotation_number TEXT NOT NULL,
  customer_id UUID REFERENCES organizations(id),
  customer_name TEXT,
  contact_person TEXT,
  project_name TEXT,
  quotation_date DATE DEFAULT CURRENT_DATE,
  validity_date DATE,
  status TEXT NOT NULL DEFAULT 'draft',
  notes TEXT,
  material_cost NUMERIC(12,2) DEFAULT 0,
  labor_cost NUMERIC(12,2) DEFAULT 0,
  accessories_cost NUMERIC(12,2) DEFAULT 0,
  transport_cost NUMERIC(12,2) DEFAULT 0,
  installation_cost NUMERIC(12,2) DEFAULT 0,
  currency TEXT DEFAULT 'EGP',
  converted_to UUID,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Quotation line items
CREATE TABLE IF NOT EXISTS quotation_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  quotation_id UUID NOT NULL REFERENCES quotations(id) ON DELETE CASCADE,
  product TEXT NOT NULL,
  description TEXT,
  quantity INTEGER DEFAULT 1,
  unit_price NUMERIC(12,2) DEFAULT 0,
  width_cm NUMERIC(8,2),
  height_cm NUMERIC(8,2),
  depth_cm NUMERIC(8,2),
  material TEXT,
  finish TEXT,
  color TEXT,
  accessories TEXT,
  installation_required BOOLEAN DEFAULT FALSE,
  delivery_required BOOLEAN DEFAULT FALSE,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS policies
ALTER TABLE quotations ENABLE ROW LEVEL SECURITY;
ALTER TABLE quotation_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "workspace_quotations" ON quotations
  FOR ALL USING (
    workspace_id IN (
      SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "workspace_quotation_items" ON quotation_items
  FOR ALL USING (
    workspace_id IN (
      SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()
    )
  );

-- Indexes
CREATE INDEX IF NOT EXISTS idx_quotations_workspace ON quotations(workspace_id);
CREATE INDEX IF NOT EXISTS idx_quotations_status ON quotations(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_quotation_items_quotation ON quotation_items(quotation_id);


-- ████ supabase/sales-orders-foundation.sql ████
-- ============================================================
-- Bumblebee ERP — Sales Orders Foundation Migration
-- ============================================================
-- OPTIONAL. Currently sales orders are stored in the work_items
-- table (type = 'sales_order') with items, payments, and
-- readiness checklist in the metadata JSON field.
--
-- Run this migration when you need dedicated tables for
-- better querying, reporting, or payment tracking.
-- ============================================================

-- Sales Orders
CREATE TABLE IF NOT EXISTS sales_orders (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  so_number TEXT NOT NULL,
  customer_type TEXT DEFAULT 'individual', -- individual | company
  customer_id UUID REFERENCES organizations(id),
  customer_name TEXT,
  contact_person TEXT,
  phone TEXT,
  address TEXT,
  city TEXT,
  company_name TEXT,
  project_name TEXT,
  project_location TEXT,
  po_number TEXT,
  payment_terms TEXT,
  source_quotation_id UUID,
  source_quotation_number TEXT,
  order_date DATE DEFAULT CURRENT_DATE,
  expected_delivery DATE,
  delivery_required BOOLEAN DEFAULT TRUE,
  installation_required BOOLEAN DEFAULT TRUE,
  status TEXT NOT NULL DEFAULT 'draft',
  notes TEXT,
  currency TEXT DEFAULT 'EGP',
  -- Production readiness
  customer_confirmed BOOLEAN DEFAULT FALSE,
  measurements_done BOOLEAN DEFAULT FALSE,
  design_approved BOOLEAN DEFAULT FALSE,
  materials_available BOOLEAN DEFAULT FALSE,
  deposit_received BOOLEAN DEFAULT FALSE,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Sales Order Items
CREATE TABLE IF NOT EXISTS sales_order_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  sales_order_id UUID NOT NULL REFERENCES sales_orders(id) ON DELETE CASCADE,
  product TEXT NOT NULL,
  description TEXT,
  quantity INTEGER DEFAULT 1,
  unit_price NUMERIC(12,2) DEFAULT 0,
  width_cm NUMERIC(8,2),
  height_cm NUMERIC(8,2),
  depth_cm NUMERIC(8,2),
  material TEXT,
  finish TEXT,
  color TEXT,
  accessories TEXT,
  sort_order INTEGER DEFAULT 0,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Sales Order Payments
CREATE TABLE IF NOT EXISTS sales_order_payments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  sales_order_id UUID NOT NULL REFERENCES sales_orders(id) ON DELETE CASCADE,
  label TEXT NOT NULL,
  amount NUMERIC(12,2) DEFAULT 0,
  paid BOOLEAN DEFAULT FALSE,
  paid_date DATE,
  notes TEXT,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS
ALTER TABLE sales_orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE sales_order_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE sales_order_payments ENABLE ROW LEVEL SECURITY;

CREATE POLICY "workspace_sales_orders" ON sales_orders
  FOR ALL USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "workspace_sales_order_items" ON sales_order_items
  FOR ALL USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

CREATE POLICY "workspace_sales_order_payments" ON sales_order_payments
  FOR ALL USING (workspace_id IN (SELECT workspace_id FROM workspace_members WHERE user_id = auth.uid()));

-- Indexes
CREATE INDEX IF NOT EXISTS idx_sales_orders_workspace ON sales_orders(workspace_id);
CREATE INDEX IF NOT EXISTS idx_sales_orders_status ON sales_orders(workspace_id, status);
CREATE INDEX IF NOT EXISTS idx_sales_orders_customer ON sales_orders(customer_id);
CREATE INDEX IF NOT EXISTS idx_so_items_order ON sales_order_items(sales_order_id);
CREATE INDEX IF NOT EXISTS idx_so_payments_order ON sales_order_payments(sales_order_id);


-- ████ supabase/pos-foundation.sql ████
-- POS Foundation Migration
-- Adds the 4 POS tables missing from the live project (present in schema.sql
-- clean-install but never applied): pos_registers, pos_transactions,
-- pos_transaction_items, branch_inventory.
-- Idempotent — safe to re-run. Paste into the Supabase dashboard SQL editor.

-- ─── pos_registers ────────────────────────────────────────
create table if not exists pos_registers (
  id            uuid        primary key default uuid_generate_v4(),
  workspace_id  uuid        not null references workspaces(id) on delete cascade,
  branch_id     uuid        not null references branches(id) on delete cascade,
  register_code text        not null,
  name          text        not null,
  name_ar       text,
  status        text        not null default 'active'
                            check (status in ('active','inactive','maintenance')),
  opened_by     uuid,
  opened_at     timestamptz,
  closed_at     timestamptz,
  float_amount  numeric     not null default 0,
  current_cash  numeric     not null default 0,
  metadata      jsonb       not null default '{}',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists pos_registers_workspace_idx on pos_registers(workspace_id);
create index if not exists pos_registers_branch_idx    on pos_registers(branch_id);

-- ─── pos_transactions ─────────────────────────────────────
create table if not exists pos_transactions (
  id                      uuid        primary key default uuid_generate_v4(),
  workspace_id            uuid        not null references workspaces(id) on delete cascade,
  branch_id               uuid        not null references branches(id) on delete cascade,
  register_id             uuid        not null references pos_registers(id) on delete cascade,
  transaction_number      text        not null,
  customer_id             uuid,
  customer_name           text,
  customer_phone          text,
  loyalty_card_number     text,
  subtotal                numeric     not null default 0,
  discount_amount         numeric     not null default 0,
  discount_percent        numeric     not null default 0,
  tax_amount              numeric     not null default 0,
  tax_rate                numeric     not null default 15,
  total                   numeric     not null default 0,
  currency                text        not null default 'SAR',
  payment_method          text        not null default 'cash'
                            check (payment_method in ('cash','card','mobile_wallet','loyalty_points','split')),
  payment_details         jsonb       not null default '{}',
  status                  text        not null default 'completed'
                            check (status in ('completed','voided','refunded','pending')),
  cashier_name            text        not null,
  notes                   text,
  receipt_printed         boolean     not null default false,
  loyalty_points_earned   integer     not null default 0,
  loyalty_points_redeemed integer     not null default 0,
  metadata                jsonb       not null default '{}',
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);

create index if not exists pos_transactions_workspace_idx on pos_transactions(workspace_id);
create index if not exists pos_transactions_branch_idx    on pos_transactions(branch_id);
create index if not exists pos_transactions_register_idx  on pos_transactions(register_id);
create index if not exists pos_transactions_created_idx   on pos_transactions(workspace_id, created_at desc);
create index if not exists pos_transactions_status_idx    on pos_transactions(workspace_id, status);

-- ─── pos_transaction_items ────────────────────────────────
create table if not exists pos_transaction_items (
  id              uuid        primary key default uuid_generate_v4(),
  workspace_id    uuid        not null references workspaces(id) on delete cascade,
  transaction_id  uuid        not null references pos_transactions(id) on delete cascade,
  product_id      uuid,
  product_name    text        not null,
  product_name_ar text,
  sku             text,
  quantity        numeric     not null default 1,
  unit_price      numeric     not null default 0,
  discount_amount numeric     not null default 0,
  discount_percent numeric    not null default 0,
  total           numeric     not null default 0,
  cost_price      numeric     not null default 0,
  branch_id       uuid        not null references branches(id) on delete cascade,
  metadata        jsonb       not null default '{}',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index if not exists pos_transaction_items_workspace_idx on pos_transaction_items(workspace_id);
create index if not exists pos_transaction_items_txn_idx       on pos_transaction_items(transaction_id);

-- ─── branch_inventory ─────────────────────────────────────
create table if not exists branch_inventory (
  id                uuid        primary key default uuid_generate_v4(),
  workspace_id      uuid        not null references workspaces(id) on delete cascade,
  branch_id         uuid        not null references branches(id) on delete cascade,
  product_id        uuid        not null,
  product_name      text        not null,
  sku               text,
  quantity          integer     not null default 0,
  reserved_quantity integer     not null default 0,
  reorder_level     integer     not null default 5,
  unit_cost         numeric     not null default 0,
  unit_price        numeric     not null default 0,
  last_restocked_at timestamptz,
  metadata          jsonb       not null default '{}',
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists branch_inventory_workspace_idx on branch_inventory(workspace_id);
create index if not exists branch_inventory_branch_idx    on branch_inventory(branch_id);
create index if not exists branch_inventory_product_idx   on branch_inventory(product_id);

-- ─── updated_at triggers ──────────────────────────────────
do $$
declare t text;
begin
  foreach t in array array[
    'pos_registers','pos_transactions','pos_transaction_items','branch_inventory'
  ] loop
    execute format('drop trigger if exists set_updated_at on %I;', t);
    execute format('
      create trigger set_updated_at
        before update on %I
        for each row execute function update_updated_at();
    ', t);
  end loop;
end $$;

-- ─── RLS (universal workspace-isolation pattern) ──────────
alter table pos_registers         enable row level security;
alter table pos_transactions      enable row level security;
alter table pos_transaction_items enable row level security;
alter table branch_inventory      enable row level security;

do $$
declare t text;
begin
  foreach t in array array[
    'pos_registers','pos_transactions','pos_transaction_items','branch_inventory'
  ] loop
    execute format('drop policy if exists "workspace_select" on %I;', t);
    execute format('drop policy if exists "workspace_insert" on %I;', t);
    execute format('drop policy if exists "workspace_update" on %I;', t);
    execute format('drop policy if exists "workspace_delete" on %I;', t);
    execute format('
      create policy "workspace_select" on %I
        for select using (is_workspace_member(workspace_id));
      create policy "workspace_insert" on %I
        for insert with check (is_workspace_member(workspace_id));
      create policy "workspace_update" on %I
        for update using (is_workspace_member(workspace_id));
      create policy "workspace_delete" on %I
        for delete using (is_workspace_admin(workspace_id));
    ', t, t, t, t);
  end loop;
end $$;

-- ─── Grants (belt-and-braces; default privileges normally cover this) ──
grant all on pos_registers, pos_transactions, pos_transaction_items, branch_inventory
  to anon, authenticated, service_role;


-- ████ supabase/staff-accounts.sql ████
-- ═══════════════════════════════════════════════════════════
-- Bumblebee — Staff Accounts, Usernames & Role Enforcement
--
-- Lets an owner/admin create a colleague's login directly (username or
-- email + a password they choose), assign an access level, and share the
-- credentials — no email round-trip. Google sign-in and invite links keep
-- working alongside it.
--
-- Run after users-access-control.sql and invite-flow.sql.
-- Idempotent: safe to run again.
-- ═══════════════════════════════════════════════════════════

create extension if not exists pgcrypto with schema extensions;

-- ─── 1. Roles: the app has 10 role templates, the base schema allowed 4 ──

alter table workspace_members drop constraint if exists workspace_members_role_check;
alter table workspace_members add constraint workspace_members_role_check
  check (role in ('owner','admin','manager','member','sales','finance','production_manager',
                  'warehouse','purchasing','qc','delivery','viewer'));

-- ─── 2. Usernames ─────────────────────────────────────────

alter table profiles add column if not exists username text;
create unique index if not exists profiles_username_key on profiles (lower(username));

-- ─── 3. Username → email, for the sign-in form ────────────
-- Returns the login email for a username so the browser can call
-- signInWithPassword. Reveals nothing for unknown names.

create or replace function email_for_username(p_username text)
returns text
language sql security definer stable
set search_path = public
as $$
  select email from profiles where lower(username) = lower(trim(p_username)) limit 1;
$$;

grant execute on function email_for_username(text) to anon, authenticated;

-- ─── 4. Create a staff account ────────────────────────────
-- Caller must be owner/admin of the workspace. Only an owner can create
-- another owner or admin. A username-only account gets a private placeholder
-- email (<username>@<workspace-slug>.staff.bumblebee) that nobody types.

create or replace function create_staff_account(
  p_workspace_id uuid,
  p_full_name    text,
  p_password     text,
  p_role         text,
  p_username     text default null,
  p_email        text default null,
  p_department   text default null,
  p_permissions  jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql security definer
set search_path = public, extensions
as $$
declare
  v_caller_role text;
  v_slug        text;
  v_username    text := nullif(lower(trim(coalesce(p_username, ''))), '');
  v_email       text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_user_id     uuid := gen_random_uuid();
begin
  select role into v_caller_role from workspace_members
   where workspace_id = p_workspace_id and user_id = auth.uid();

  if v_caller_role is null or v_caller_role not in ('owner', 'admin') then
    raise exception 'Only a workspace owner or admin can create accounts' using errcode = '42501';
  end if;
  if p_role in ('owner', 'admin') and v_caller_role <> 'owner' then
    raise exception 'Only the owner can create another owner or admin' using errcode = '42501';
  end if;
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'Password must be at least 8 characters' using errcode = '22023';
  end if;
  if v_username is null and v_email is null then
    raise exception 'Give the account a username or an email' using errcode = '22023';
  end if;
  if v_username is not null and v_username !~ '^[a-z0-9][a-z0-9._-]{2,31}$' then
    raise exception 'Usernames are 3–32 characters: letters, numbers, dot, dash, underscore' using errcode = '22023';
  end if;
  if v_username is not null and exists (select 1 from profiles where lower(username) = v_username) then
    raise exception 'That username is taken' using errcode = '23505';
  end if;

  if v_email is null then
    select slug into v_slug from workspaces where id = p_workspace_id;
    v_email := v_username || '@' || v_slug || '.staff.bumblebee';
  end if;
  if exists (select 1 from auth.users where lower(email) = v_email) then
    raise exception 'An account with that email already exists' using errcode = '23505';
  end if;

  -- GoTrue reads the token columns as strings: they must be '' rather than NULL.
  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change
  ) values (
    '00000000-0000-0000-0000-000000000000', v_user_id, 'authenticated', 'authenticated',
    v_email, crypt(p_password, gen_salt('bf')), now(),
    jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email')),
    jsonb_build_object('full_name', coalesce(p_full_name, ''), 'username', v_username),
    now(), now(), '', '', '', ''
  );

  insert into auth.identities (
    id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at
  ) values (
    gen_random_uuid(), v_user_id, v_user_id::text, 'email',
    jsonb_build_object('sub', v_user_id::text, 'email', v_email, 'email_verified', true),
    now(), now(), now()
  );

  -- on_auth_user_created has inserted the profile row; stamp the username.
  update profiles set username = v_username, full_name = coalesce(p_full_name, full_name)
   where id = v_user_id;

  insert into workspace_members (workspace_id, user_id, role, department, permissions, display_name, status, invited_by, invited_at)
  values (p_workspace_id, v_user_id, p_role, p_department, coalesce(p_permissions, '{}'::jsonb),
          p_full_name, 'active', auth.uid(), now());

  return jsonb_build_object('user_id', v_user_id, 'email', v_email, 'username', v_username);
end;
$$;

revoke all on function create_staff_account(uuid, text, text, text, text, text, text, jsonb) from public, anon;
grant execute on function create_staff_account(uuid, text, text, text, text, text, text, jsonb) to authenticated;

-- ─── 5. Reset a staff member's password ───────────────────

create or replace function reset_staff_password(p_workspace_id uuid, p_user_id uuid, p_password text)
returns void
language plpgsql security definer
set search_path = public, extensions
as $$
declare
  v_caller_role text;
  v_target_role text;
begin
  select role into v_caller_role from workspace_members where workspace_id = p_workspace_id and user_id = auth.uid();
  select role into v_target_role from workspace_members where workspace_id = p_workspace_id and user_id = p_user_id;
  if v_caller_role not in ('owner', 'admin') or v_target_role is null then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if v_target_role in ('owner', 'admin') and v_caller_role <> 'owner' then
    raise exception 'Only the owner can reset an owner or admin password' using errcode = '42501';
  end if;
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'Password must be at least 8 characters' using errcode = '22023';
  end if;
  update auth.users set encrypted_password = crypt(p_password, gen_salt('bf')), updated_at = now()
   where id = p_user_id;
end;
$$;

revoke all on function reset_staff_password(uuid, uuid, text) from public, anon;
grant execute on function reset_staff_password(uuid, uuid, text) to authenticated;

-- ─── 6. Members list for the Users & Access page ──────────
-- workspace_members has no email; profiles does. One read, member-only.

create or replace function list_workspace_members(p_workspace_id uuid)
returns table (
  id uuid, user_id uuid, role text, department text, display_name text, status text,
  permissions jsonb, joined_at timestamptz, email text, username text, avatar_url text,
  last_sign_in_at timestamptz, provider text
)
language sql security definer stable
set search_path = public
as $$
  select m.id, m.user_id, m.role, m.department, coalesce(m.display_name, p.full_name), m.status,
         m.permissions, m.joined_at,
         case when u.email like '%.staff.bumblebee' then null else u.email end,
         p.username, p.avatar_url, u.last_sign_in_at,
         coalesce(u.raw_app_meta_data->>'provider', 'email')
    from workspace_members m
    join profiles p on p.id = m.user_id
    join auth.users u on u.id = m.user_id
   where m.workspace_id = p_workspace_id
     and exists (select 1 from workspace_members me
                  where me.workspace_id = p_workspace_id and me.user_id = auth.uid())
   order by m.joined_at;
$$;

grant execute on function list_workspace_members(uuid) to authenticated;

-- ─── 7. Change role / status (owner/admin) ────────────────

create or replace function update_workspace_member(
  p_workspace_id uuid, p_user_id uuid, p_role text default null, p_status text default null,
  p_department text default null, p_permissions jsonb default null
)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_caller_role text;
  v_target_role text;
begin
  select role into v_caller_role from workspace_members where workspace_id = p_workspace_id and user_id = auth.uid();
  select role into v_target_role from workspace_members where workspace_id = p_workspace_id and user_id = p_user_id;
  if v_caller_role not in ('owner', 'admin') or v_target_role is null then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if v_target_role = 'owner' and p_user_id <> auth.uid() then
    raise exception 'The owner cannot be changed by someone else' using errcode = '42501';
  end if;
  if (coalesce(p_role, '') in ('owner', 'admin') or v_target_role = 'admin') and v_caller_role <> 'owner' then
    raise exception 'Only the owner can grant or change admin access' using errcode = '42501';
  end if;
  update workspace_members set
    role        = coalesce(p_role, role),
    status      = coalesce(p_status, status),
    department  = coalesce(p_department, department),
    permissions = coalesce(p_permissions, permissions),
    updated_at  = now()
  where workspace_id = p_workspace_id and user_id = p_user_id;
end;
$$;

grant execute on function update_workspace_member(uuid, uuid, text, text, text, jsonb) to authenticated;

-- ─── 8. Suspended members cannot read the workspace ───────
-- The app hides a suspended user's workspace; this makes the database agree.

create or replace function is_active_member(ws_id uuid)
returns boolean language sql security definer stable
set search_path = public
as $$
  select exists (select 1 from workspace_members
                  where workspace_id = ws_id and user_id = auth.uid()
                    and coalesce(status, 'active') = 'active');
$$;

grant execute on function is_active_member(uuid) to authenticated;


-- ████ supabase/documents.sql ████
-- ═══════════════════════════════════════════════════════════
-- Bumblebee — Issued documents: numbering, references, invoices & receipts
--
-- Every document that goes on paper (quotation, sales order, purchase
-- request/order, goods receipt, production order, invoice, receipt,
-- delivery note, POS sale, QC report…) gets its number from the DATABASE,
-- one gap-free sequence per workspace, document type and year:
--     QT-2026-00001, SO-2026-00001, INV-2026-00001, RCT-2026-00001 …
-- Numbers are unique, can't be edited once issued, and issued documents
-- can't be deleted — they are cancelled/voided instead, so the paper trail
-- always matches the system.
--
-- Invoices are created FROM a confirmed sales order and can never add up to
-- more than the order; receipts are recorded AGAINST an invoice and can never
-- exceed its balance. Both rules live in this file, not in the browser.
--
-- Run after full-install.sql. Idempotent.
-- ═══════════════════════════════════════════════════════════

-- ─── 1. Sequences ─────────────────────────────────────────

create table if not exists document_sequences (
  workspace_id uuid    not null references workspaces(id) on delete cascade,
  doc_type     text    not null,
  period       integer not null,
  last_value   integer not null default 0,
  primary key (workspace_id, doc_type, period)
);
alter table document_sequences enable row level security;
-- No policies on purpose: only next_document_number() touches it.

create or replace function document_prefix(p_doc_type text)
returns text language sql immutable as $$
  select case p_doc_type
    when 'quotation'        then 'QT'
    when 'sales_order'      then 'SO'
    when 'purchase_request' then 'PR'
    when 'purchase_order'   then 'PO'
    when 'goods_receipt'    then 'GRN'
    when 'production_order' then 'MO'
    when 'invoice'          then 'INV'
    when 'receipt'          then 'RCT'
    when 'delivery_note'    then 'DN'
    when 'installation'     then 'INS'
    when 'pos_sale'         then 'POS'
    when 'qc_inspection'    then 'QC'
    when 'design_brief'     then 'DB'
    when 'site_visit'       then 'SV'
    else null
  end;
$$;

create or replace function next_document_number(p_workspace_id uuid, p_doc_type text)
returns text
language plpgsql security definer
set search_path = public
as $$
declare
  v_prefix text := document_prefix(p_doc_type);
  v_year   integer := extract(year from (now() at time zone 'Africa/Cairo'))::integer;
  v_value  integer;
begin
  if v_prefix is null then
    raise exception 'Unknown document type: %', p_doc_type using errcode = '22023';
  end if;
  if not exists (select 1 from workspace_members
                  where workspace_id = p_workspace_id and user_id = auth.uid()
                    and coalesce(status, 'active') = 'active') then
    raise exception 'Not a member of this workspace' using errcode = '42501';
  end if;

  insert into document_sequences (workspace_id, doc_type, period, last_value)
  values (p_workspace_id, p_doc_type, v_year, 1)
  on conflict (workspace_id, doc_type, period)
  do update set last_value = document_sequences.last_value + 1
  returning last_value into v_value;

  return v_prefix || '-' || v_year || '-' || lpad(v_value::text, 5, '0');
end;
$$;

revoke all on function next_document_number(uuid, text) from public, anon;
grant execute on function next_document_number(uuid, text) to authenticated;

-- ─── 2. work_items documents: one number column, unique, immutable ─────

alter table work_items add column if not exists doc_number text;

-- Carry numbers already stored in metadata into the column.
update work_items set doc_number = coalesce(
  metadata->>'doc_number', metadata->>'quotation_number', metadata->>'so_number', metadata->>'po_number', metadata->>'pr_number')
where doc_number is null
  and type in ('quotation','sales_order','purchase_request','purchase_order')
  and coalesce(metadata->>'doc_number', metadata->>'quotation_number', metadata->>'so_number', metadata->>'po_number', metadata->>'pr_number') is not null;

create unique index if not exists work_items_doc_number_key
  on work_items (workspace_id, type, doc_number) where doc_number is not null;

create or replace function guard_issued_work_item()
returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' then
    if old.doc_number is not null and new.doc_number is distinct from old.doc_number then
      raise exception 'Document number % can''t be changed once issued', old.doc_number using errcode = '42501';
    end if;
    return new;
  end if;
  -- DELETE
  if old.type in ('quotation','sales_order','purchase_request','purchase_order')
     and old.doc_number is not null and old.status <> 'draft' then
    raise exception '% is issued and can''t be deleted — cancel it instead', old.doc_number using errcode = '42501';
  end if;
  return old;
end;
$$;
do $$ begin if to_regclass('work_items') is not null then execute 'drop trigger if exists guard_issued_work_item on work_items'; end if; end $$;
create trigger guard_issued_work_item before update or delete on work_items
  for each row execute function guard_issued_work_item();

-- ─── 3. Other numbered tables: unique numbers ─────────────

create unique index if not exists production_orders_number_key on production_orders (workspace_id, po_number);
create unique index if not exists pos_transactions_number_key on pos_transactions (workspace_id, transaction_number);
do $$ begin
  if to_regclass('deliveries') is not null then
    execute 'create unique index if not exists deliveries_number_key on deliveries (workspace_id, delivery_number)';
  end if;
end $$;

-- ─── 4. Invoices ──────────────────────────────────────────

alter table invoices add column if not exists sales_order_id uuid references work_items(id) on delete restrict;
alter table invoices add column if not exists issue_date     date    not null default current_date;
alter table invoices add column if not exists subtotal       numeric not null default 0;
alter table invoices add column if not exists discount_amount numeric not null default 0;
alter table invoices add column if not exists tax_rate       numeric not null default 0;
alter table invoices add column if not exists tax_amount     numeric not null default 0;
alter table invoices add column if not exists amount_paid    numeric not null default 0;
alter table invoices add column if not exists void_reason    text;
alter table invoices alter column currency set default 'EGP';

alter table invoices drop constraint if exists invoices_status_check;
alter table invoices add constraint invoices_status_check
  check (status in ('draft','sent','partially_paid','paid','overdue','cancelled','void'));

create unique index if not exists invoices_number_key on invoices (workspace_id, number);
create index if not exists invoices_sales_order_idx on invoices (sales_order_id);

-- ─── 5. Payments = receipts ───────────────────────────────

alter table payments add column if not exists receipt_number text;
alter table payments add column if not exists sales_order_id uuid references work_items(id) on delete restrict;
alter table payments add column if not exists reference      text;
alter table payments add column if not exists received_by    text;
alter table payments add column if not exists void_reason    text;
alter table payments alter column currency set default 'EGP';

alter table payments drop constraint if exists payments_status_check;
alter table payments add constraint payments_status_check
  check (status in ('pending','completed','failed','refunded','void'));

create unique index if not exists payments_receipt_number_key on payments (workspace_id, receipt_number) where receipt_number is not null;

-- Keeps an invoice's paid amount and status in step with its receipts.
create or replace function refresh_invoice_balance(p_invoice_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_paid numeric;
  v_inv  invoices%rowtype;
begin
  select * into v_inv from invoices where id = p_invoice_id;
  if not found or v_inv.status in ('void','cancelled') then return; end if;
  select coalesce(sum(amount), 0) into v_paid from payments
   where invoice_id = p_invoice_id and status = 'completed';
  update invoices set
    amount_paid = v_paid,
    status = case
      when v_paid >= amount and amount > 0 then 'paid'
      when v_paid > 0 then 'partially_paid'
      when due_date is not null and due_date < current_date then 'overdue'
      else 'sent' end,
    paid_date = case when v_paid >= amount and amount > 0 then current_date else null end,
    updated_at = now()
  where id = p_invoice_id;
end;
$$;

-- Issued money documents are voided, never deleted.
create or replace function guard_money_delete()
returns trigger language plpgsql as $$
begin
  if tg_table_name = 'invoices' and old.status <> 'draft' then
    raise exception 'Invoice % is issued and can''t be deleted — void it instead', old.number using errcode = '42501';
  end if;
  if tg_table_name = 'payments' and old.receipt_number is not null then
    raise exception 'Receipt % can''t be deleted — void it instead', old.receipt_number using errcode = '42501';
  end if;
  return old;
end;
$$;
do $$ begin if to_regclass('invoices') is not null then execute 'drop trigger if exists guard_invoice_delete on invoices'; end if; end $$;
create trigger guard_invoice_delete before delete on invoices for each row execute function guard_money_delete();
do $$ begin if to_regclass('payments') is not null then execute 'drop trigger if exists guard_payment_delete on payments'; end if; end $$;
create trigger guard_payment_delete before delete on payments for each row execute function guard_money_delete();

-- ─── 6. Sales order money helpers ─────────────────────────

-- Grand total of a sales order as the app computes it (lib/money.ts):
-- line nets → order discount → tax. total_amount on the row wins when set.
create or replace function sales_order_total(p_so work_items)
returns numeric language plpgsql stable as $$
declare
  v_sub  numeric := 0;
  v_line jsonb;
  v_gross numeric;
  v_disc numeric;
  v_od   numeric := coalesce((p_so.metadata->>'order_discount')::numeric, 0);
  v_after numeric;
begin
  if p_so.total_amount is not null and p_so.total_amount > 0 then
    return p_so.total_amount;
  end if;
  for v_line in select * from jsonb_array_elements(coalesce(p_so.metadata->'items', '[]'::jsonb)) loop
    v_gross := coalesce((v_line->>'qty')::numeric, 0) * coalesce((v_line->>'unitPrice')::numeric, 0);
    v_disc := coalesce((v_line->>'discount')::numeric, 0);
    if v_disc > 0 then
      if v_line->>'discountType' = 'fixed' then v_gross := greatest(0, v_gross - v_disc);
      else v_gross := v_gross * (1 - least(v_disc, 100) / 100); end if;
    end if;
    v_sub := v_sub + v_gross;
  end loop;
  if v_od > 0 then
    if p_so.metadata->>'order_discount_type' = 'fixed' then v_after := v_sub - least(v_od, v_sub);
    else v_after := v_sub * (1 - least(v_od, 100) / 100); end if;
  else v_after := v_sub; end if;
  return round(v_after * (1 + coalesce((p_so.metadata->>'tax_rate')::numeric, 0) / 100), 2);
end;
$$;

-- ─── 7. Create an invoice from a sales order ──────────────
-- Full balance by default, or a part (deposit/instalment). Refuses drafts,
-- cancelled orders, and anything that would invoice more than the order.

create or replace function create_invoice_from_sales_order(
  p_sales_order_id uuid,
  p_amount   numeric default null,
  p_due_date date    default null,
  p_note     text    default null
)
returns invoices
language plpgsql security definer
set search_path = public
as $$
declare
  v_so        work_items%rowtype;
  v_total     numeric;
  v_invoiced  numeric;
  v_remaining numeric;
  v_amount    numeric;
  v_rate      numeric;
  v_number    text;
  v_inv       invoices%rowtype;
begin
  select * into v_so from work_items where id = p_sales_order_id and type = 'sales_order' for update;
  if not found then raise exception 'Sales order not found' using errcode = 'P0002'; end if;
  if not is_active_member(v_so.workspace_id) then raise exception 'Not allowed' using errcode = '42501'; end if;
  if v_so.status in ('draft', 'cancelled') then
    raise exception 'Confirm the sales order before invoicing it' using errcode = '22023';
  end if;

  v_total := sales_order_total(v_so);
  select coalesce(sum(amount), 0) into v_invoiced from invoices
   where sales_order_id = v_so.id and status not in ('void', 'cancelled');
  v_remaining := round(v_total - v_invoiced, 2);
  v_amount := round(coalesce(p_amount, v_remaining), 2);

  if v_remaining <= 0 then raise exception 'This order is already fully invoiced' using errcode = '22023'; end if;
  if v_amount <= 0 then raise exception 'Invoice amount must be more than zero' using errcode = '22023'; end if;
  if v_amount > v_remaining then
    raise exception 'Only % is left to invoice on this order', v_remaining using errcode = '22023';
  end if;

  v_rate := coalesce((v_so.metadata->>'tax_rate')::numeric, 0);
  v_number := next_document_number(v_so.workspace_id, 'invoice');

  insert into invoices (workspace_id, number, org_name_en, organization_id, sales_order_id, amount, currency,
                        status, issue_date, due_date, subtotal, tax_rate, tax_amount, metadata)
  values (
    v_so.workspace_id, v_number,
    coalesce(v_so.metadata->>'customer_name', v_so.metadata->>'company_name', v_so.title_en),
    v_so.organization_id, v_so.id, v_amount,
    coalesce(v_so.metadata->>'currency', 'EGP'),
    'sent', current_date, p_due_date,
    round(v_amount / (1 + v_rate / 100), 2), v_rate, round(v_amount - v_amount / (1 + v_rate / 100), 2),
    jsonb_build_object(
      'sales_order_number', v_so.doc_number,
      'quotation_number', v_so.metadata->>'source_quotation_number',
      'order_total', v_total,
      'is_partial', v_amount < v_remaining or v_invoiced > 0,
      'items', coalesce(v_so.metadata->'items', '[]'::jsonb),
      'order_discount', v_so.metadata->'order_discount',
      'order_discount_type', v_so.metadata->'order_discount_type',
      'customer_phone', v_so.metadata->>'phone',
      'customer_address', concat_ws(', ', v_so.metadata->>'address', v_so.metadata->>'city'),
      'note', p_note,
      'issued_by', auth.uid()
    )
  )
  returning * into v_inv;

  return v_inv;
end;
$$;

revoke all on function create_invoice_from_sales_order(uuid, numeric, date, text) from public, anon;
grant execute on function create_invoice_from_sales_order(uuid, numeric, date, text) to authenticated;

-- ─── 8. Record a receipt against an invoice ───────────────

create or replace function record_invoice_payment(
  p_invoice_id uuid,
  p_amount     numeric,
  p_method     text default 'cash',
  p_reference  text default null,
  p_paid_at    timestamptz default now()
)
returns payments
language plpgsql security definer
set search_path = public
as $$
declare
  v_inv     invoices%rowtype;
  v_balance numeric;
  v_number  text;
  v_pay     payments%rowtype;
  v_name    text;
begin
  select * into v_inv from invoices where id = p_invoice_id for update;
  if not found then raise exception 'Invoice not found' using errcode = 'P0002'; end if;
  if not is_active_member(v_inv.workspace_id) then raise exception 'Not allowed' using errcode = '42501'; end if;
  if v_inv.status in ('void', 'cancelled', 'draft') then
    raise exception 'Invoice % is %, payments can''t be recorded', v_inv.number, v_inv.status using errcode = '22023';
  end if;
  if p_method not in ('cash', 'bank_transfer', 'card', 'cheque', 'mobile_wallet', 'instapay') then
    raise exception 'Unknown payment method %', p_method using errcode = '22023';
  end if;

  v_balance := round(v_inv.amount - v_inv.amount_paid, 2);
  if p_amount is null or p_amount <= 0 then raise exception 'Payment must be more than zero' using errcode = '22023'; end if;
  if round(p_amount, 2) > v_balance then
    raise exception 'Only % is due on invoice %', v_balance, v_inv.number using errcode = '22023';
  end if;

  select coalesce(nullif(display_name, ''), p.full_name, p.username) into v_name
    from workspace_members m join profiles p on p.id = m.user_id
   where m.workspace_id = v_inv.workspace_id and m.user_id = auth.uid();

  v_number := next_document_number(v_inv.workspace_id, 'receipt');
  insert into payments (workspace_id, invoice_id, sales_order_id, receipt_number, amount, currency, method,
                        status, paid_at, reference, received_by, metadata)
  values (v_inv.workspace_id, v_inv.id, v_inv.sales_order_id, v_number, round(p_amount, 2), v_inv.currency, p_method,
          'completed', coalesce(p_paid_at, now()), p_reference, v_name,
          jsonb_build_object('invoice_number', v_inv.number,
                             'sales_order_number', v_inv.metadata->>'sales_order_number',
                             'customer', v_inv.org_name_en,
                             'balance_before', v_balance,
                             'balance_after', v_balance - round(p_amount, 2)))
  returning * into v_pay;

  perform refresh_invoice_balance(v_inv.id);
  return v_pay;
end;
$$;

revoke all on function record_invoice_payment(uuid, numeric, text, text, timestamptz) from public, anon;
grant execute on function record_invoice_payment(uuid, numeric, text, text, timestamptz) to authenticated;

-- ─── 9. Void (never delete) ───────────────────────────────

create or replace function void_invoice(p_invoice_id uuid, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare v_inv invoices%rowtype;
begin
  select * into v_inv from invoices where id = p_invoice_id for update;
  if not found then raise exception 'Invoice not found' using errcode = 'P0002'; end if;
  if not exists (select 1 from workspace_members where workspace_id = v_inv.workspace_id and user_id = auth.uid()
                  and role in ('owner','admin','finance','manager') and coalesce(status,'active') = 'active') then
    raise exception 'Only owners, admins, managers or finance can void invoices' using errcode = '42501';
  end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Give a reason for voiding' using errcode = '22023'; end if;
  if exists (select 1 from payments where invoice_id = p_invoice_id and status = 'completed') then
    raise exception 'Void the receipts on % first', v_inv.number using errcode = '22023';
  end if;
  update invoices set status = 'void', void_reason = p_reason, updated_at = now() where id = p_invoice_id;
end;
$$;

create or replace function void_payment(p_payment_id uuid, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare v_pay payments%rowtype;
begin
  select * into v_pay from payments where id = p_payment_id for update;
  if not found then raise exception 'Receipt not found' using errcode = 'P0002'; end if;
  if not exists (select 1 from workspace_members where workspace_id = v_pay.workspace_id and user_id = auth.uid()
                  and role in ('owner','admin','finance','manager') and coalesce(status,'active') = 'active') then
    raise exception 'Only owners, admins, managers or finance can void receipts' using errcode = '42501';
  end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Give a reason for voiding' using errcode = '22023'; end if;
  update payments set status = 'void', void_reason = p_reason, updated_at = now() where id = p_payment_id;
  if v_pay.invoice_id is not null then perform refresh_invoice_balance(v_pay.invoice_id); end if;
end;
$$;

revoke all on function void_invoice(uuid, text) from public, anon;
revoke all on function void_payment(uuid, text) from public, anon;
grant execute on function void_invoice(uuid, text) to authenticated;
grant execute on function void_payment(uuid, text) to authenticated;

-- Invoices and receipts are only written through the functions above.
-- Members can still read them (workspace policies from schema.sql).
do $$ begin if to_regclass('invoices') is not null then execute 'drop policy if exists "workspace_insert" on invoices'; end if; end $$;
do $$ begin if to_regclass('invoices') is not null then execute 'drop policy if exists "workspace_update" on invoices'; end if; end $$;
do $$ begin if to_regclass('payments') is not null then execute 'drop policy if exists "workspace_insert" on payments'; end if; end $$;
do $$ begin if to_regclass('payments') is not null then execute 'drop policy if exists "workspace_update" on payments'; end if; end $$;

-- Company details for printed documents live in workspaces.settings.company.
-- Admins (not just the owner) may edit workspace settings.
do $$ begin if to_regclass('workspaces') is not null then execute 'drop policy if exists "workspaces_update" on workspaces'; end if; end $$;
create policy "workspaces_update" on workspaces
  for update using (
    owner_id = auth.uid()
    or exists (select 1 from workspace_members m
               where m.workspace_id = workspaces.id and m.user_id = auth.uid()
                 and m.role in ('owner','admin') and coalesce(m.status,'active') = 'active')
  );


-- ████ supabase/fix-trigger-rls.sql ████
-- ============================================================
-- Bumblebee — Fix: handle_new_user trigger + profiles RLS
--
-- Run this in Supabase SQL Editor.
--
-- Fixes two bugs that cause "Database error saving new user":
--   1. handle_new_user() missing SET search_path = public
--   2. profiles_insert RLS policy blocks trigger (auth.uid() = null
--      at signup time — no session exists yet when the trigger fires)
-- ============================================================


-- ── 1. Recreate the trigger function with correct search_path ──
--
-- SECURITY DEFINER makes the function run as its owner (postgres).
-- SET search_path = public ensures it can resolve "profiles" even
-- when called from the auth schema trigger context.

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email, full_name, avatar_url)
  values (
    new.id,
    coalesce(new.email, ''),
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    new.raw_user_meta_data->>'avatar_url'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;


-- ── 2. Recreate the trigger (idempotent) ──────────────────────
do $$ begin if to_regclass('auth.users') is not null then execute 'drop trigger if exists on_auth_user_created on auth.users'; end if; end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();


-- ── 3. Fix profiles RLS INSERT policy ─────────────────────────
--
-- Old policy: with check (id = auth.uid())
--   → Fails for trigger inserts because auth.uid() = null at signup time.
--
-- New policy: with check (true)
--   → Allows any insert. Safe because:
--     a) profiles.id is a FK → auth.users(id): only valid auth UIDs accepted.
--     b) The SECURITY DEFINER trigger controls who inserts on signup.
--     c) WorkspaceSetup upserts the same row with the authenticated user's
--        own ID — still safe in practice.
--   Reads and updates still enforce auth.uid() = id.
do $$ begin if to_regclass('public.profiles') is not null then execute 'drop policy if exists "profiles_insert" on public.profiles'; end if; end $$;

create policy "profiles_insert" on public.profiles
  for insert with check (true);


-- ── 4. Ensure authenticated role has table-level INSERT grant ──
--
-- Needed if the fix-grants migration hasn't been run yet.

grant usage on schema public to authenticated, anon;

grant select, insert, update, delete on
  public.profiles,
  public.workspaces,
  public.workspace_members,
  public.organizations,
  public.people,
  public.work_items,
  public.deals,
  public.invoices,
  public.payments,
  public.expenses,
  public.resources,
  public.activity_events
to authenticated;

grant select on public.profiles to anon;


-- ── DONE ──────────────────────────────────────────────────────
-- Verify: sign up a new email/password user.
-- Supabase Auth should create the auth.users row,
-- the trigger fires and inserts into public.profiles,
-- user lands on WorkspaceSetup to create their workspace.
-- ============================================================


-- ████ supabase/fix-workspaces-select-rls.sql ████
-- ============================================================
-- Bumblebee — Fix: workspaces SELECT policy blocks INSERT…RETURNING
--
-- Run this in Supabase SQL Editor.
--
-- Root cause: workspaces_select uses is_workspace_member(id),
-- but during onboarding the workspace_members row doesn't exist
-- yet when the INSERT…RETURNING fires. PostgreSQL evaluates the
-- SELECT policy on RETURNING rows, so the insert fails with
-- 42501 even though the INSERT policy itself passes.
--
-- Fix: let the workspace owner always read their own workspace.
-- ============================================================
do $$ begin if to_regclass('workspaces') is not null then execute 'drop policy if exists "workspaces_select" on workspaces'; end if; end $$;

CREATE POLICY "workspaces_select" ON workspaces
  FOR SELECT USING (owner_id = auth.uid() OR is_workspace_member(id));


-- ████ supabase/enable-crm-rls.sql ████
-- ============================================================
-- Bumblebee — turn on RLS for the CRM tables
--
-- schema.sql creates the workspace_select/insert/update/delete policies for
-- these tables, but never runs ENABLE ROW LEVEL SECURITY on them — so the
-- policies were inert and, after fix-grants.sql, anyone holding the public
-- anon key could read every customer, lead, note and communication log.
--
-- Enabling RLS here makes the existing policies apply. Any table that somehow
-- lacks them gets the same workspace pattern, so nothing is left locked out
-- or wide open. Idempotent.
-- ============================================================

do $$
declare
  t text;
begin
  foreach t in array array[
    'crm_customers', 'crm_timeline_events', 'crm_tasks', 'crm_notes', 'crm_leads', 'crm_alerts',
    'crm_activity_feed', 'customer_ai_summaries', 'customer_communication_logs',
    'customer_relationships', 'loyalty_accounts'
  ] loop
    if to_regclass(t) is null then
      continue;
    end if;

    execute format('alter table %I enable row level security', t);

    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t and policyname = 'workspace_select') then
      execute format('create policy "workspace_select" on %I for select using (is_workspace_member(workspace_id))', t);
    end if;
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t and policyname = 'workspace_insert') then
      execute format('create policy "workspace_insert" on %I for insert with check (is_workspace_member(workspace_id))', t);
    end if;
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t and policyname = 'workspace_update') then
      execute format('create policy "workspace_update" on %I for update using (is_workspace_member(workspace_id))', t);
    end if;
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t and policyname = 'workspace_delete') then
      execute format('create policy "workspace_delete" on %I for delete using (is_workspace_admin(workspace_id))', t);
    end if;
  end loop;
end $$;


-- ████ supabase/fix-grants.sql ████
-- ═══════════════════════════════════════════════════════════
-- RESTORE DEFAULT SUPABASE ROLE GRANTS
--
-- Symptom: every API call returns 42501 "permission denied for
-- table ..." → white page after sign-in, all syncs failing.
-- Cause: a script revoked table privileges from the API roles.
-- Supabase's model is: GRANT table access + RLS policies filter
-- rows. RLS stays enabled — this only restores the grants.
--
-- Safe to run multiple times.
-- ═══════════════════════════════════════════════════════════

GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;

GRANT ALL ON ALL TABLES    IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated, service_role;

-- Make sure future tables get the grants automatically again
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT ALL ON TABLES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT ALL ON SEQUENCES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT ALL ON FUNCTIONS TO anon, authenticated, service_role;
